INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-06-01-cloud-native-ai-infra-digest', 'Cloud Native and AI Infrastructure Digest: June 1, 2026', 'Fresh analysis covers the Miasma npm supply-chain attack, vLLM serving on DGX Spark, vLLM-Omni GGUF quantization, and CNCF guidance on dynamic Swift service configuration.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"miasma-turns-npm-trusted-publishing-against-red-hat-cloud-packages"},"content":[{"type":"text","text":"Miasma turns npm trusted publishing against Red Hat cloud packages"}]},{"type":"paragraph","content":[{"type":"text","text":"SafeDep and Wiz disclosed Miasma on June 1: an npm supply-chain attack against packages in the "},{"type":"text","text":"@redhat-cloud-services","marks":[{"type":"code"}]},{"type":"text","text":" namespace."}]},{"type":"paragraph","content":[{"type":"text","text":"The attacker did not bypass provenance. They made provenance point at the wrong thing. According to SafeDep, short-lived "},{"type":"text","text":"oidc-*","marks":[{"type":"code"}]},{"type":"text","text":" branches were added to three RedHatInsights repositories, trusted-publishing workflows were changed, and modified packages were pushed with valid npm provenance. The missing control was branch authorization: the registry could prove which repository and workflow produced the artifact, but not that the publish came from a protected branch operators trusted."}]},{"type":"paragraph","content":[{"type":"text","text":"The malicious packages executed during "},{"type":"text","text":"preinstall","marks":[{"type":"code"}]},{"type":"text","text":". They downloaded Bun when it was not already present, then scanned for cloud, Kubernetes, npm, GitHub, Vault, and password-manager credentials. Wiz says most affected versions had been revoked by its 13:00 UTC update, with two still remaining at publication time."}]},{"type":"paragraph","content":[{"type":"text","text":"Platform teams should treat trusted-publishing configuration as production infrastructure. Bind publish workflows to protected branches or environments wherever the registry supports it, and block known-bad package versions before CI can run lifecycle scripts."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"SafeDep","marks":[{"type":"link","attrs":{"href":"https://safedep.io/redhat-cloud-services-hit-by-mini-shai-hulud-npm-worm/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"Wiz","marks":[{"type":"link","attrs":{"href":"https://www.wiz.io/blog/miasma-supply-chain-attack-targeting-redhat-npm-packages","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"vllm-publishes-dgx-spark-serving-guidance-for-nemotron-3-super"},"content":[{"type":"text","text":"vLLM publishes DGX Spark serving guidance for Nemotron-3-Super"}]},{"type":"paragraph","content":[{"type":"text","text":"The vLLM project published a June 1 deployment guide for running "},{"type":"text","text":"nvidia/NVIDIA-Nemotron-3-Super-120B-A12B-NVFP4","marks":[{"type":"code"}]},{"type":"text","text":" through vLLM on NVIDIA DGX Spark."}]},{"type":"paragraph","content":[{"type":"text","text":"The guide is useful because DGX Spark is not a normal data-center GPU target. Its GB10 Grace Blackwell SoC exposes a unified 128 GB CPU/GPU memory pool, so vLLM settings such as "},{"type":"text","text":"--gpu-memory-utilization","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--max-model-len","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"--max-num-seqs","marks":[{"type":"code"}]},{"type":"text","text":" affect the operating system, container runtime, model weights, and KV cache together."}]},{"type":"paragraph","content":[{"type":"text","text":"The published example uses the OpenAI-compatible vLLM server image, "},{"type":"text","text":"--max-model-len 131072","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--gpu-memory-utilization 0.85","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"--max-num-seqs 4","marks":[{"type":"code"}]},{"type":"text","text":", and model-specific parser flags. vLLM reports a five-scenario single-Spark evaluation with median decode throughput in the 22.7 to 23.7 tokens/sec range after warm-up, and explicitly frames the result as recipe-specific rather than a general DGX Spark ceiling."}]},{"type":"paragraph","content":[{"type":"text","text":"This matters for local and small-batch inference work because the post turns \"will this fit?\" into a runbook shape: pin an image, pre-stage weights, warm JIT paths before first use, and watch KV-cache plus TTFT metrics from "},{"type":"text","text":"/metrics","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM","marks":[{"type":"link","attrs":{"href":"https://vllm.ai/blog/2026-06-01-vllm-dgx-spark","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"vllm-omni-documents-gguf-quantization-for-diffusion-serving"},"content":[{"type":"text","text":"vLLM-Omni documents GGUF quantization for diffusion serving"}]},{"type":"paragraph","content":[{"type":"text","text":"The vLLM-Omni documentation added June 1 guidance for GGUF quantization in diffusion-serving paths."}]},{"type":"paragraph","content":[{"type":"text","text":"The implementation loads pre-quantized diffusion transformer weights from GGUF while keeping the rest of the pipeline on the base Hugging Face checkpoint for tokenizer, text encoder, scheduler, and VAE state. The docs list validated adapter paths for Qwen-Image, Z-Image, and FLUX.2-klein, while multi-stage omni, TTS, BAGEL, and GLM-Image paths remain unvalidated or require model-specific adapters."}]},{"type":"paragraph","content":[{"type":"text","text":"For serving, the documented online path passes "},{"type":"text","text":"--diffusion-quantization-config ''{\"method\":\"gguf\",\"gguf_model\":\"...\"}''","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"vllm serve --omni","marks":[{"type":"code"}]},{"type":"text","text":". Hardware support is documented for NVIDIA Ampere, Ada/Hopper, and Blackwell GPUs, with ROCm marked unverified and Ascend marked unsupported."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical value is clearer failure behavior: unsupported models should fail with an adapter error instead of silently using a generic tensor-name mapper."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM-Omni","marks":[{"type":"link","attrs":{"href":"https://docs.vllm.ai/projects/vllm-omni/en/latest/user_guide/quantization/gguf/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"cncf-covers-dynamic-configuration-patterns-for-swift-services-on-kubernetes"},"content":[{"type":"text","text":"CNCF covers dynamic configuration patterns for Swift services on Kubernetes"}]},{"type":"paragraph","content":[{"type":"text","text":"CNCF published a June 1 technical post on Swift Configuration for cloud native Swift services."}]},{"type":"paragraph","content":[{"type":"text","text":"The post focuses on operational configuration mechanics rather than language marketing: ordered configuration providers, dot-notation keys that map across files and environment variables, ConfigMap-style file reloading, and immutable snapshots so a request does not observe half of one configuration version and half of another."}]},{"type":"paragraph","content":[{"type":"text","text":"The Kubernetes-specific detail is the torn-read problem during hot reload. Swift Configuration''s provider model replaces a complete snapshot atomically and keeps the previous valid snapshot when a reload is malformed, which is the behavior platform teams generally want from ConfigMap-mounted runtime configuration."}]},{"type":"paragraph","content":[{"type":"text","text":"This is niche, but it is technically useful for teams running Swift services on Kubernetes because it gives the runtime a first-class model for precedence, reloads, and consistent reads instead of ad hoc "},{"type":"text","text":"ProcessInfo.environment","marks":[{"type":"code"}]},{"type":"text","text":" plus hand-rolled file parsing."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"CNCF","marks":[{"type":"link","attrs":{"href":"https://www.cncf.io/blog/2026/06/01/dynamic-configuration-for-cloud-native-swift-services/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 1, 2026"}]},{"type":"horizontalRule"}]}', 1780272000000, 1790105224000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-06-01-cloud-native-ai-infra-digest', 'rawkode', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-06-05-envoy-istio-nccl', 'Envoy, Istio, and NCCL ship operator-facing fixes', 'Envoy and Istio published June 4 security and mesh patch releases, while NVIDIA NCCL 2.30.7-1 added zero-SM collectives and symmetric-memory improvements for GPU communication.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Envoy, Istio, and NCCL all shipped changes in the last 24 hours that affect production operators: proxy memory-exhaustion fixes, Istio Gateway API and ambient repairs, and lower-overhead GPU collective paths."}]},{"type":"heading","attrs":{"level":2,"id":"envoy-patches-http2-header-accounting-and-oauth2-filter-bugs"},"content":[{"type":"text","text":"Envoy patches HTTP/2 header accounting and OAuth2 filter bugs"}]},{"type":"paragraph","content":[{"type":"text","text":"Envoy v1.38.1 was tagged on June 4 with security fixes also backported across the currently supported 1.37 and 1.36 release lines. The headline fix is CVE-2026-47774: HTTP/2 streams now reset when decoded header data exceeds configured limits, and uncompressed cookies count against both request-header byte and header-count limits."}]},{"type":"paragraph","content":[{"type":"text","text":"The release also applies the nghttp2 CVE-2026-27135 patch and fixes two OAuth2 filter issues: a timing side channel in HMAC verification and a crash path where AES-CBC token-cookie decryption could appear to succeed with the wrong secret. Operators should also note two behavior changes in v1.38.1: upstream transport failure details are no longer sent in downstream response bodies, and load-balancer rebuild coalescing during EDS batch updates is now opt-in."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Envoy v1.38.1 release notes","marks":[{"type":"link","attrs":{"href":"https://www.envoyproxy.io/docs/envoy/v1.38.1/version_history/v1.38/v1.38.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 4, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"istio-1301-adds-gateway-api-checks-and-ambient-fixes"},"content":[{"type":"text","text":"Istio 1.30.1 adds Gateway API checks and ambient fixes"}]},{"type":"paragraph","content":[{"type":"text","text":"Istio 1.30.1 shipped on June 4 with the Envoy CVE-2026-47774 fix plus several operator-visible repairs in Gateway API, ambient mode, and multicluster handling. The release adds "},{"type":"text","text":"istioctl analyze","marks":[{"type":"code"}]},{"type":"text","text":" check "},{"type":"text","text":"IST0176","marks":[{"type":"code"}]},{"type":"text","text":" for stale Gateway API CRDs, because older CRDs can cause istiod to filter resources silently after an Istio 1.30 upgrade."}]},{"type":"paragraph","content":[{"type":"text","text":"Gateway API handling gets fixes for "},{"type":"text","text":"BackendTLSPolicy","marks":[{"type":"code"}]},{"type":"text","text":" conflicts, HTTPS "},{"type":"text","text":"ListenerSet","marks":[{"type":"code"}]},{"type":"text","text":" certificate delivery with manually deployed gateways, and invalid "},{"type":"text","text":"HTTPRoute","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"GRPCRoute","marks":[{"type":"code"}]},{"type":"text","text":" header filter reporting. Ambient mode fixes include a multi-network waypoint routing bug, a CNI "},{"type":"text","text":"concurrent map writes","marks":[{"type":"code"}]},{"type":"text","text":" panic, and a traffic-distribution leak where one not-ready-service setting could affect unrelated services using the same preset."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Istio 1.30.1 release notes","marks":[{"type":"link","attrs":{"href":"https://istio.io/latest/news/releases/1.30.x/announcing-1.30.1/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 4, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"nccl-2307-1-adds-zero-sm-collectives"},"content":[{"type":"text","text":"NCCL 2.30.7-1 adds zero-SM collectives"}]},{"type":"paragraph","content":[{"type":"text","text":"NVIDIA published NCCL v2.30.7-1 on June 4 with new hierarchical zero-SM "},{"type":"text","text":"AllGather","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"All2all","marks":[{"type":"code"}]},{"type":"text","text":" collectives. The release notes describe an inter-node path through an RMA CPU proxy and an intra-node path through copy engines, enabled with the "},{"type":"text","text":"NCCL_CTA_POLICY_ZERO","marks":[{"type":"code"}]},{"type":"text","text":" flag, so communication can overlap with GPU compute more cleanly."}]},{"type":"paragraph","content":[{"type":"text","text":"The release also expands GIN with an experimental GPU Push Interface backend, stronger signal and fence semantics, traffic-class control, and resource-sharing knobs. Symmetric-memory changes include RMA plugin restructuring, asymmetric buffer sizes during window registration, CUDA graph capture support for window registration, and batched copy-engine operations in the RMA put/wait path; experimental MPS plus MLOPart support allows up to two ranks per physical GPU."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"NVIDIA NCCL v2.30.7-1 release","marks":[{"type":"link","attrs":{"href":"https://github.com/NVIDIA/nccl/releases/tag/v2.30.7-1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 4, 2026"}]},{"type":"horizontalRule"}]}', 1780617600000, 1780663994000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-06-05-envoy-istio-nccl', 'rawkode', 0);
