INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-06-09-nccl-opentelemetry-cert-manager', 'NCCL EP, OpenTelemetry Collector, and cert-manager ship runtime changes', 'NVIDIA published NCCL EP v0.1.0 for MoE expert-parallel communication, OpenTelemetry Collector v0.154.0 tightened builder behavior and queue config handling, and cert-manager v1.21.0-alpha.1 added Gateway API and issuer fixes.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three fresh releases landed in the last 24 hours across AI/HPC communication, telemetry collection, and certificate automation."}]},{"type":"heading","attrs":{"level":2,"id":"nccl-ep-v010-targets-moe-expert-parallel-communication"},"content":[{"type":"text","text":"NCCL EP v0.1.0 targets MoE expert-parallel communication"}]},{"type":"paragraph","content":[{"type":"text","text":"NVIDIA published NCCL EP v0.1.0 on June 8 as an NCCL API extension for Mixture-of-Experts communication. It adds dispatch and combine primitives for Expert Parallelism across distributed GPU systems on top of NCCL Device API LSA and GIN operations."}]},{"type":"paragraph","content":[{"type":"text","text":"The release changes EP tensor memory ownership to caller-managed allocations, separates handle initialization from routing updates for CUDA Graph-compatible data paths, lets users set NCCL EP SM usage, associates EP tensors with NCCL Windows for zero-copy paths, and adds active-rank masks so failed ranks can be excluded without aborting. It also moves HT mode to JIT compilation, adds Multi-node NVLINK support, removes rank-count limits in LSA teams, and removes CUDA IPC dependencies by migrating to NCCL infrastructure."}]},{"type":"paragraph","content":[{"type":"text","text":"For teams serving MoE models, the concrete change is a communication path built around dispatch and combine rather than treating expert routing as generic collectives."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"NVIDIA NCCL EP v0.1.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/NVIDIA/nccl/releases/tag/nccl-ep-v0.1.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 8, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"opentelemetry-collector-v01540-makes-builder-skip-behavior-real"},"content":[{"type":"text","text":"OpenTelemetry Collector v0.154.0 makes builder skip behavior real"}]},{"type":"paragraph","content":[{"type":"text","text":"OpenTelemetry Collector released v1.60.0/v0.154.0 on June 8. The user-visible breaking change fixes "},{"type":"text","text":"ocb --skip-get-modules","marks":[{"type":"code"}]},{"type":"text","text":" so it no longer regenerates "},{"type":"text","text":"go.mod","marks":[{"type":"code"}]},{"type":"text","text":", matching the builder flag contract."}]},{"type":"paragraph","content":[{"type":"text","text":"The release adds an "},{"type":"text","text":"include_insecure_cipher_suites","marks":[{"type":"code"}]},{"type":"text","text":" config option in "},{"type":"text","text":"configtls","marks":[{"type":"code"}]},{"type":"text","text":", with insecure suites disabled by default, and adds "},{"type":"text","text":"ExposedHeaders","marks":[{"type":"code"}]},{"type":"text","text":" to HTTP CORS config. It also fixes a collector startup panic when "},{"type":"text","text":"sending_queue::sizer","marks":[{"type":"code"}]},{"type":"text","text":" is configured while batching is disabled."}]},{"type":"paragraph","content":[{"type":"text","text":"For collector distribution maintainers, the builder change matters because the flag now leaves existing module files untouched."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"OpenTelemetry Collector v1.60.0/v0.154.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/open-telemetry/opentelemetry-collector/releases/tag/v0.154.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 8, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"cert-manager-v1210-alpha1-adds-gateway-api-and-issuer-plumbing"},"content":[{"type":"text","text":"cert-manager v1.21.0-alpha.1 adds Gateway API and issuer plumbing"}]},{"type":"paragraph","content":[{"type":"text","text":"cert-manager published v1.21.0-alpha.1 on June 8 as a testing-only pre-release. It adds Venafi OAuth token request observability plus an "},{"type":"text","text":"AuthFailed","marks":[{"type":"code"}]},{"type":"text","text":" Issuer condition reason, a controller flag to propagate Helm "},{"type":"text","text":"global.commonLabels","marks":[{"type":"code"}]},{"type":"text","text":" to ACME HTTP-01 solver Pods, Services, Ingresses, and Gateway API HTTPRoutes, and Gateway API options for ignored TLS listeners and additional listener protocols."}]},{"type":"paragraph","content":[{"type":"text","text":"Bug fixes include DNS issuer secret validation before readiness, missing issuer-finalizer RBAC for order controller owner references, namespace-scoped metrics collector startup behavior, a Venafi TPP signing regression, 30-second negative caching for CRD-missing discovery in the "},{"type":"text","text":"certificateRequestApproval","marks":[{"type":"code"}]},{"type":"text","text":" webhook, and an infinite re-issuance loop when an issuer returns an already expired certificate."}]},{"type":"paragraph","content":[{"type":"text","text":"This is not an upgrade target, but it is a useful preview of where the 1.21 line is tightening issuer diagnostics and Gateway API automation."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"cert-manager v1.21.0-alpha.1 release","marks":[{"type":"link","attrs":{"href":"https://github.com/cert-manager/cert-manager/releases/tag/v1.21.0-alpha.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 8, 2026"}]},{"type":"horizontalRule"}]}', 1780963200000, 1780997406000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-06-09-nccl-opentelemetry-cert-manager', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-06-09-nccl-opentelemetry-cert-manager', 'opentelemetry', 0);
