INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-06-13-vllm-sglang-kubernetes-kueue-helm', 'vLLM, SGLang, Kubernetes, Kueue, and Helm ship runtime fixes', 'vLLM and SGLang released AI serving updates, while Kubernetes, Kueue, and Helm shipped scheduler, queueing, and release-management fixes.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Five fresh releases landed in the last 24 hours across AI serving, Kubernetes scheduling, workload queueing, and Helm release management."}]},{"type":"heading","attrs":{"level":2,"id":"vllm-v0230-expands-model-runner-v2-and-kv-cache-offload"},"content":[{"type":"text","text":"vLLM v0.23.0 expands Model Runner V2 and KV-cache offload"}]},{"type":"paragraph","content":[{"type":"text","text":"vLLM published v0.23.0 on June 12 with 408 commits across model support, serving internals, distributed execution, and hardware backends. Model Runner V2 is now selected by default for Llama and Mistral dense models, after previously landing for Qwen3."}]},{"type":"paragraph","content":[{"type":"text","text":"The release adds an object-store secondary tier to the KV-cache offloading framework, enables HMA by default for capable connectors, and adds per-request offloading policy through the "},{"type":"text","text":"on_new_request","marks":[{"type":"code"}]},{"type":"text","text":" lifecycle hook. It also moves vLLM toward Transformers v5, deprecates v4 support, expands the experimental Rust frontend with streaming "},{"type":"text","text":"generate","marks":[{"type":"code"}]},{"type":"text","text":", dynamic LoRA, "},{"type":"text","text":"/version","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"/server_info","marks":[{"type":"code"}]},{"type":"text","text":" endpoints, and continues DeepSeek-V4 work across attention, RoPE, sparse MLA metadata, EPLB, and XPU decode paths."}]},{"type":"paragraph","content":[{"type":"text","text":"For operators running mixed model fleets, the practical change is broader default coverage for the newer execution path plus more explicit cache-tiering controls for disaggregated serving."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM v0.23.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/vllm-project/vllm/releases/tag/v0.23.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 12, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"sglang-v0513-makes-spec-v2-the-default-speculative-path"},"content":[{"type":"text","text":"SGLang v0.5.13 makes Spec V2 the default speculative path"}]},{"type":"paragraph","content":[{"type":"text","text":"SGLang released v0.5.13 on June 13 with runtime changes across speculative decoding, scheduler overhead, CUDA graph capture, hybrid-model cache offload, and DeepSeek V4 serving. The main serving change is that Spec V2 is now the default speculative-decoding path, with tree drafting across Triton, FA3, MLA, and AITER backends, including "},{"type":"text","text":"page_size > 1","marks":[{"type":"code"}]},{"type":"text","text":" and Mamba or hybrid-linear models."}]},{"type":"paragraph","content":[{"type":"text","text":"The release deprecates Spec V1, moves EAGLE and MTP onto the unified V2 worker, and adds faster top-k equals 1 drafting. It also extends Piecewise and Breakable CUDA Graph coverage to DSA models, Kimi-K2.5, and DeepSeek V4; enables HiCache by default for hybrid SWA and Mamba models through UnifiedTree; and adds DeepSeek V4 context-parallel serving, sparse FlashMLA, FP4 indexer support, SM120 support, and DeepEP waterfill load balancing."}]},{"type":"paragraph","content":[{"type":"text","text":"This matters for inference teams because speculative decode, CUDA graph capture, and hierarchical KV-cache offload are becoming default-path behavior rather than optional tuning around the core server."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"SGLang v0.5.13 release","marks":[{"type":"link","attrs":{"href":"https://github.com/sgl-project/sglang/releases/tag/v0.5.13","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 13, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"kubernetes-ships-june-patch-releases-with-dra-and-storage-fixes"},"content":[{"type":"text","text":"Kubernetes ships June patch releases with DRA and storage fixes"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes published "},{"type":"text","text":"v1.36.2","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/releases/tag/v1.36.2","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"v1.35.6","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/releases/tag/v1.35.6","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"v1.34.9","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/releases/tag/v1.34.9","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", and "},{"type":"text","text":"v1.33.13","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/releases/tag/v1.33.13","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 12. The v1.36.2 changelog includes DRA scheduler fixes for mutually exclusive device partitions, Pods stuck Pending when multi-node and per-node claims are mixed, and a kube-scheduler panic when "},{"type":"text","text":"allocationMode: All","marks":[{"type":"code"}]},{"type":"text","text":" selects a device using shared counters."}]},{"type":"paragraph","content":[{"type":"text","text":"The backports also include endpoint-controller panic fixes for Services with empty "},{"type":"text","text":"IPFamilies","marks":[{"type":"code"}]},{"type":"text","text":", CSI republish handling so kubelet does not delete the mount directory after a failed "},{"type":"text","text":"NodePublishVolume","marks":[{"type":"code"}]},{"type":"text","text":" call, and a 1.34+ regression fix for Secret API objects containing binary non-UTF-8 data in container environment values. Kubernetes v1.36.2 is also built with Go 1.26.4."}]},{"type":"paragraph","content":[{"type":"text","text":"For clusters testing DRA or CSI republish behavior, this patch set is more than routine version churn: it fixes scheduler and kubelet failure modes that can directly affect workload placement and volume contents."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes releases","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/releases","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 12, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"kueue-v0181-and-v0175-repair-dra-tas-and-queue-status-behavior"},"content":[{"type":"text","text":"Kueue v0.18.1 and v0.17.5 repair DRA, TAS, and queue status behavior"}]},{"type":"paragraph","content":[{"type":"text","text":"Kueue published "},{"type":"text","text":"v0.18.1","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/kueue/releases/tag/v0.18.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" and "},{"type":"text","text":"v0.17.5","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/kueue/releases/tag/v0.17.5","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 12. The v0.18.1 release fixes pending DRA Workloads not being requeued when a "},{"type":"text","text":"DeviceClass","marks":[{"type":"code"}]},{"type":"text","text":" is deleted or its "},{"type":"text","text":"extendedResourceName","marks":[{"type":"code"}]},{"type":"text","text":" changes, rejects partitionable-device "},{"type":"text","text":"sources","marks":[{"type":"code"}]},{"type":"text","text":" config when the related feature gate is disabled, and avoids hot reconcile loops for deterministic DRA resolution failures."}]},{"type":"paragraph","content":[{"type":"text","text":"Both supported lines include fixes for regular Workloads being rejected when "},{"type":"text","text":"ElasticJobsViaWorkloadSlicesWithTAS","marks":[{"type":"code"}]},{"type":"text","text":" is enabled, LocalQueue status updates failing when a referenced ClusterQueue has more than 16 flavors, and TAS topology assignment errors being treated as "},{"type":"text","text":"Fit","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"NoFit","marks":[{"type":"code"}]},{"type":"text","text":". The releases also correct unset borrowing and lending limits in metrics to report "},{"type":"text","text":"+Inf","marks":[{"type":"code"}]},{"type":"text","text":", matching unconstrained behavior instead of reporting zero."}]},{"type":"paragraph","content":[{"type":"text","text":"Batch platform teams using Kueue for accelerator queues should treat this as a scheduler correctness release, especially if DRA or topology-aware scheduling is enabled."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kueue v0.18.1 release","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/kueue/releases/tag/v0.18.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 12, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"helm-v421-and-v3211-patch-cli-and-sdk-edge-cases"},"content":[{"type":"text","text":"Helm v4.2.1 and v3.21.1 patch CLI and SDK edge cases"}]},{"type":"paragraph","content":[{"type":"text","text":"Helm released "},{"type":"text","text":"v4.2.1","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v4.2.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" and "},{"type":"text","text":"v3.21.1","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v3.21.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 12. Helm 4.2.1 fixes a data race in "},{"type":"text","text":"FailingKubeClient.RecordedWaitOptions","marks":[{"type":"code"}]},{"type":"text","text":", success messages that were written to stderr instead of stdout, false warnings when resolving version range constraints, and a "},{"type":"text","text":"WaitForDelete","marks":[{"type":"code"}]},{"type":"text","text":" race where the status observer could cancel the watch too early."}]},{"type":"paragraph","content":[{"type":"text","text":"Helm 3.21.1 fixes a nil REST client getter panic in ClientOnly CRD install flows, keeps registry credentials during plain-HTTP fallback with "},{"type":"text","text":"oras-go","marks":[{"type":"code"}]},{"type":"text","text":" v2.6.1, and moves the v3 line to Go 1.26. Both v4.2.1 and v3.21.1 bump "},{"type":"text","text":"golang.org/x/net","marks":[{"type":"code"}]},{"type":"text","text":" to v0.55.0 to address GO-2026-5026."}]},{"type":"paragraph","content":[{"type":"text","text":"The release is most relevant to teams embedding Helm as an SDK or depending on deterministic CLI output in automation."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Helm v4.2.1 release","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v4.2.1","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 12, 2026"}]},{"type":"horizontalRule"}]}', 1781308800000, 1790105224000);
