INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-06-20-runc-1-5-prometheus-3-13-talos', 'runc 1.5.0 ships stable, Prometheus 3.13 enters RC, Talos patches etcd leak', 'runc cut its first stable 1.5 release with libpathrs hardening and a new support policy, Prometheus opened a 3.13.0 release candidate with new PromQL functions, and Talos v1.12.9 fixed an etcd client resource leak.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three primary-source releases landed in the last 24 hours across container runtimes, metrics, and the node OS. It was a quiet window, so this is a short digest rather than a padded one."}]},{"type":"heading","attrs":{"level":2,"id":"runc-150-cuts-the-first-stable-release-of-the-15-branch"},"content":[{"type":"text","text":"runc 1.5.0 cuts the first stable release of the 1.5 branch"}]},{"type":"paragraph","content":[{"type":"text","text":"The OCI reference runtime published "},{"type":"text","text":"runc 1.5.0","marks":[{"type":"link","attrs":{"href":"https://github.com/opencontainers/runc/releases/tag/v1.5.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 19, described by maintainers as the somewhat-delayed first stable release of the 1.5.z line. It rolls up the 1.5.0-rc series, including the fix for CVE-2026-41579, a low-severity issue where a malicious image with a "},{"type":"text","text":"/dev","marks":[{"type":"code"}]},{"type":"text","text":" symlink could gain limited write access to the host filesystem."}]},{"type":"paragraph","content":[{"type":"text","text":"The 1.5 line continues runc''s move onto "},{"type":"text","text":"libpathrs","marks":[{"type":"code"}]},{"type":"text","text":" for safer path resolution: builds using the libpathrs tag now require v0.2.5 or later, and both "},{"type":"text","text":"runc version","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"runc features","marks":[{"type":"code"}]},{"type":"text","text":" report libpathrs build details. The release upgrades go-criu to v8.3.0, drops binary size from roughly 16MB to 14MB, and fixes a long-standing bug where the "},{"type":"text","text":"org.opencontainers.runc.version","marks":[{"type":"code"}]},{"type":"text","text":" annotation carried a stray newline that broke parsing in downstream tools."}]},{"type":"paragraph","content":[{"type":"text","text":"1.5.0 is also the first stable release under runc''s revised support policy: the 1.2.z and earlier branches are end-of-life, 1.3.z receives only high-severity CVE fixes through October 2026, and 1.4.z moves to security and significant bugfixes only."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"runc 1.5.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/opencontainers/runc/releases/tag/v1.5.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 19, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"prometheus-3130-rc0-adds-scalar-min_ofmax_of-and-metadata-search-endpoints"},"content":[{"type":"text","text":"Prometheus 3.13.0-rc.0 adds scalar min_of/max_of and metadata search endpoints"}]},{"type":"paragraph","content":[{"type":"text","text":"Prometheus published "},{"type":"text","text":"v3.13.0-rc.0","marks":[{"type":"link","attrs":{"href":"https://github.com/prometheus/prometheus/releases/tag/v3.13.0-rc.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 19 as a testing-only release candidate for the 3.13 line. PromQL gains experimental scalar "},{"type":"text","text":"min_of(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"max_of(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" functions and support for smoothed/anchored rate over native histograms."}]},{"type":"paragraph","content":[{"type":"text","text":"The candidate adds experimental API search endpoints for metric names, label names, and label values, a "},{"type":"text","text":"storage.tsdb.chunk_encoding.floats","marks":[{"type":"code"}]},{"type":"text","text":" flag to select float chunk encoding at runtime, and new scrape-time internal labels for per-target control over classic and native histogram conversion. Container images for the 3.13 line are now also published to the GitHub Container Registry, alongside a batch of TSDB and PromQL bugfixes, including range-query alignment and histogram handling in "},{"type":"text","text":"resets()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"changes()","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a preview rather than an upgrade target, but the new scalar functions and metadata search endpoints are worth testing for teams building query tooling on top of the Prometheus API."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Prometheus v3.13.0-rc.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/prometheus/prometheus/releases/tag/v3.13.0-rc.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 19, 2026"}]},{"type":"horizontalRule"},{"type":"heading","attrs":{"level":2,"id":"talos-v1129-fixes-an-etcd-client-leak-and-tightens-oom-victim-selection"},"content":[{"type":"text","text":"Talos v1.12.9 fixes an etcd client leak and tightens OOM victim selection"}]},{"type":"paragraph","content":[{"type":"text","text":"Sidero Labs released "},{"type":"text","text":"Talos v1.12.9","marks":[{"type":"link","attrs":{"href":"https://github.com/siderolabs/talos/releases/tag/v1.12.9","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on June 19 with 18 commits from 5 contributors. The release fixes an etcd client resource leak in the legacy Upgrade API and raises the file-descriptor limit for etcd, both of which matter for long-running control-plane nodes."}]},{"type":"paragraph","content":[{"type":"text","text":"It also recreates the DNS server when the host DNS runner restarts, makes OOM victim selection follow stricter QoS ordering, relaxes LUKS header and hostname validation, and reverts CoreDNS to 1.14.2 for stability. The node image ships Linux 6.18.35, containerd 2.2.5, runc 1.3.6, CoreDNS 1.14.2, and Go 1.25.11, with security updates pulled in via containerd 2.2.5 and OpenSSL 3.6.3."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Talos v1.12.9 release","marks":[{"type":"link","attrs":{"href":"https://github.com/siderolabs/talos/releases/tag/v1.12.9","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" - June 19, 2026"}]},{"type":"horizontalRule"}]}', 1781913600000, 1781953221000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-06-20-runc-1-5-prometheus-3-13-talos', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-06-20-runc-1-5-prometheus-3-13-talos', 'kubernetes', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-06-20-runc-1-5-prometheus-3-13-talos', 'prometheus', 1);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-09-18-gloo-interrupted-validation', 'Gloo Gateway Fixes Interrupted Validation That Could Drop Listeners', 'Four Gloo Gateway patch releases stop interrupted Envoy validation from being cached as a configuration failure, which could remove a listener during WAF validation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Gloo Gateway could mistake an interrupted Envoy validation process for invalid configuration. That false result was then cached and acted upon like a genuine rejection. In the most severe documented case, an interruption during WAF plugin validation could remove a listener with no automatic recovery path."}]},{"type":"paragraph","content":[{"type":"text","text":"The fix distinguishes a cancelled context or killed Envoy validation process from a completed validation failure. Gloo now discards the incomplete translation instead of publishing it or writing its status. The previously published xDS snapshot remains in the cache until a later translation completes successfully. A genuine configuration rejection still follows the existing rejection path."}]},{"type":"paragraph","content":[{"type":"text","text":"Solo shipped the correction on 18 September 2026 in "},{"type":"text","text":"1.19.23","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.19.23","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"1.20.25","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.20.25","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"1.21.16","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.21.16","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", and "},{"type":"text","text":"1.22.4","marks":[{"type":"link","attrs":{"href":"https://github.com/solo-io/gloo/releases/tag/v1.22.4","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":". The project has not stated an earliest affected version, so those fixed branches should not be read as a complete vulnerable-version range."}]},{"type":"paragraph","content":[{"type":"text","text":"The change also separates operational interruption signals from bad configuration. "},{"type":"text","text":"api.gloo.solo.io/translator/validation_interruption_skips","marks":[{"type":"code"}]},{"type":"text","text":", labelled by "},{"type":"text","text":"proxy_name","marks":[{"type":"code"}]},{"type":"text","text":", counts translations skipped while retaining the existing xDS snapshot. Admission interruptions increment "},{"type":"text","text":"validation.gateway.solo.io/resources_validation_incomplete","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"resources_rejected","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Operators using Gloo’s Envoy validation path, especially deployments with WAF configuration, should upgrade to the fixed patch for their release line. Alert on sustained increases in "},{"type":"text","text":"validation_interruption_skips","marks":[{"type":"code"}]},{"type":"text","text":": they indicate that a proxy is retaining its previous configuration because new translations are not completing."}]}]}', 1789689600000, 1789816434000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-09-18-gloo-interrupted-validation', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-09-18-gloo-interrupted-validation', 'kubernetes', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-09-18-gloo-interrupted-validation', 'envoy', 1);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('2026-09-19-externaldns-023-dry-run-crd-registry', 'ExternalDNS 0.23.0 Fixes Dry-Run Mutations and Changes the CRD Registry Namespace Default', 'ExternalDNS 0.23.0 prevents NS1 and Alibaba Cloud changes during dry-run, while CRD registry users must pin their existing DNSRecord namespace before upgrading.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ExternalDNS "},{"type":"text","text":"v0.23.0","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/external-dns/releases/tag/v0.23.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", released on 18 September, corrects two providers that violated the central expectation of "},{"type":"text","text":"--dry-run","marks":[{"type":"code"}]},{"type":"text","text":": they still changed DNS records. Before this release, the NS1 provider executed creates, updates and deletes despite dry-run mode. The "},{"type":"text","text":"NS1 fix","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/external-dns/pull/6693","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" now stops all three operations."}]},{"type":"paragraph","content":[{"type":"text","text":"Alibaba Cloud had a narrower but still consequential failure. Public and private record updates, plus private-zone deletes, continued to mutate provider state. Creates and public-zone deletes already returned without making changes. The "},{"type":"text","text":"v0.23.0 fix","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/external-dns/pull/6699","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" closes the remaining paths. Operators using either provider should not treat dry-run output from earlier releases as proof that no write occurred."}]},{"type":"paragraph","content":[{"type":"text","text":"The upgrade trap affects only deployments using "},{"type":"text","text":"--registry=crd","marks":[{"type":"code"}]},{"type":"text","text":". In v0.22, "},{"type":"text","text":"--namespace","marks":[{"type":"code"}]},{"type":"text","text":" both scoped watched sources and selected where ExternalDNS stored its "},{"type":"text","text":"DNSRecord","marks":[{"type":"code"}]},{"type":"text","text":" ownership objects. "},{"type":"text","text":"v0.23.0 separates those concerns","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes-sigs/external-dns/pull/6606","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":": "},{"type":"text","text":"--namespace","marks":[{"type":"code"}]},{"type":"text","text":" now scopes sources, while the new "},{"type":"text","text":"--crd-registry-namespace","marks":[{"type":"code"}]},{"type":"text","text":" selects registry storage. If unset, storage defaults to the namespace where ExternalDNS runs, rather than the previous "},{"type":"text","text":"--namespace","marks":[{"type":"code"}]},{"type":"text","text":" value."}]},{"type":"paragraph","content":[{"type":"text","text":"Before upgrading a CRD-registry deployment, identify the namespace containing its existing "},{"type":"text","text":"DNSRecord","marks":[{"type":"code"}]},{"type":"text","text":" objects and set "},{"type":"text","text":"--crd-registry-namespace","marks":[{"type":"code"}]},{"type":"text","text":" explicitly to that namespace. This keeps the new controller pointed at its existing ownership state."}]}]}', 1789776000000, 1789816396000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('2026-09-19-externaldns-023-dry-run-crd-registry', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('2026-09-19-externaldns-023-dry-run-crd-registry', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('aks-critical-privilege-escalation-cve-2026-33105', 'CVE-2026-33105: AKS Critical Privilege Escalation Hits CVSS 10.0', 'Microsoft disclosed a CVSS 10.0 privilege escalation vulnerability in Azure Kubernetes Service. Specific technical details are still sparse, but the confirmed characteristics make this one worth watching.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microsoft published CVE-2026-33105 on April 3, and the headline numbers are alarming: CVSS 10.0, the maximum possible score, for a privilege escalation vulnerability in Azure Kubernetes Service."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s what is confirmed from the official advisory:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Category:","marks":[{"type":"bold"}]},{"type":"text","text":" Improper authorization (CWE-285)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Attack vector:","marks":[{"type":"bold"}]},{"type":"text","text":" Network — no local access required"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Privileges required:","marks":[{"type":"bold"}]},{"type":"text","text":" None"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User interaction:","marks":[{"type":"bold"}]},{"type":"text","text":" None required"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scope:","marks":[{"type":"bold"}]},{"type":"text","text":" Changed — meaning a successful exploit can affect resources beyond the initially targeted component"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Impact:","marks":[{"type":"bold"}]},{"type":"text","text":" High across confidentiality, integrity, and availability"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"That combination — remote, unauthenticated, scope-changing, full-impact — justifies the maximum CVSS score. An attacker exploiting this could potentially escalate to broad cluster control."}]},{"type":"paragraph","content":[{"type":"text","text":"What we don''t know yet","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The specific vulnerable component within AKS has not been publicly identified. No affected version range has been confirmed, and patch availability hasn''t been officially detailed as of this writing. The EPSS score sits around 0.05%, meaning active exploitation in the near term is considered unlikely despite the severity rating. Microsoft has not reported in-the-wild exploitation."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a high-severity, low-clarity vulnerability. The details Microsoft has published are intentionally sparse at this stage, which is common practice to limit exploitation before the patch window closes. Treat any article — including this one — with appropriate skepticism if it describes specific attack paths or internal AKS components. No such detail has been publicly disclosed."}]},{"type":"paragraph","content":[{"type":"text","text":"What you can do now","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The uncertainty doesn''t mean inaction. Managed control plane vulnerabilities like this are exactly the scenario where your existing hygiene determines blast radius. Three things worth checking regardless of patch status:"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cluster role bindings you didn''t create.","marks":[{"type":"bold"}]},{"type":"text","text":" If you can''t explain why a binding exists, investigate it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Service accounts with more permissions than they need.","marks":[{"type":"bold"}]},{"type":"text","text":" The principle of least privilege matters most when authorization controls are the attack surface."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"API server audit logs.","marks":[{"type":"bold"}]},{"type":"text","text":" If you''re not shipping these somewhere queryable, you wouldn''t know if someone had exploited this before any patch landed."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Monitor the "},{"type":"text","text":"Microsoft Security Response Center","marks":[{"type":"link","attrs":{"href":"https://msrc.microsoft.com/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" for updated guidance on affected versions and patch availability. When details are confirmed, the priority level for this one is clear."}]}]}', 1775347200000, 1775405070000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('aks-critical-privilege-escalation-cve-2026-33105', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('aks-critical-privilege-escalation-cve-2026-33105', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('backstage-1-51-catalog-perf-ms-graph-incremental', 'Backstage 1.51 takes catalog list queries from seconds to milliseconds', 'Backstage v1.51.0 rewrites the entity listing and facets paths against PostgreSQL indexes, adds incremental Microsoft Graph ingestion, and ships breaking changes to navigation, OIDC defaults, and PortableSchema.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Backstage v1.51.0 dropped on May 19. The catalog gets the largest gains, but the release also carries several breaking changes that platform teams will need to handle on upgrade."}]},{"type":"heading","attrs":{"level":2,"id":"catalog-query-rewrites"},"content":[{"type":"text","text":"Catalog query rewrites"}]},{"type":"paragraph","content":[{"type":"text","text":"The entity listing endpoint now lets PostgreSQL walk the "},{"type":"text","text":"(key, value, entity_id)","marks":[{"type":"code"}]},{"type":"text","text":" index in sorted order and short-circuit on "},{"type":"text","text":"LIMIT","marks":[{"type":"code"}]},{"type":"text","text":", which the release notes describe as \"reducing typical paginated list times from seconds to milliseconds.\" The facets endpoint switches from "},{"type":"text","text":"WHERE entity_id IN (subquery)","marks":[{"type":"code"}]},{"type":"text","text":" to an inner join, \"with measured improvements from ~1.2x to 7x.\" A missing index on "},{"type":"text","text":"relations.target_entity_ref","marks":[{"type":"code"}]},{"type":"text","text":" is now added, removing full sequential scans on orphan deletion, ancestry, and eager-pruning queries. Large installations are pointed at pre-deployment SQL so the migration does not block startup."}]},{"type":"paragraph","content":[{"type":"text","text":"One behavioural change to know about: entity pagination now excludes entities that lack the requested sort field, which changes total counts and navigation."}]},{"type":"heading","attrs":{"level":2,"id":"incremental-microsoft-graph-ingestion"},"content":[{"type":"text","text":"Incremental Microsoft Graph ingestion"}]},{"type":"paragraph","content":[{"type":"text","text":"A new cursor-based Microsoft Graph user/group provider replaces the in-memory bulk load. Each burst processes a single page of up to 999 users or 100 groups, and the cursor is persisted so pod restarts resume from the last completed page. Disabled users are now filtered by default; ingesting them requires explicit configuration."}]},{"type":"heading","attrs":{"level":2,"id":"breaking-changes"},"content":[{"type":"text","text":"Breaking changes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NavItemBlueprint","marks":[{"type":"code"}]},{"type":"text","text":" is removed from "},{"type":"text","text":"@backstage/frontend-plugin-api","marks":[{"type":"code"}]},{"type":"text","text":"; navigation items are discovered from "},{"type":"text","text":"PageBlueprint","marks":[{"type":"code"}]},{"type":"text","text":" extensions based on their "},{"type":"text","text":"title","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"icon","marks":[{"type":"code"}]},{"type":"text","text":" params."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PortableSchema.schema","marks":[{"type":"code"}]},{"type":"text","text":" is now a method — direct property access like "},{"type":"text","text":"schema.type","marks":[{"type":"code"}]},{"type":"text","text":" is no longer supported."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OIDC default allow-list patterns are tightened; custom MCP clients need explicit entries."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A new alpha TracingService unifies span emission across plugins and bridges OpenTelemetry context across async boundaries."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Backstage v1.51.0","marks":[{"type":"link","attrs":{"href":"https://github.com/backstage/backstage/releases/tag/v1.51.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 19, 2026."}]}]}', 1779235200000, 1779276044000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('backstage-1-51-catalog-perf-ms-graph-incremental', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('backstage-1-51-catalog-perf-ms-graph-incremental', 'backstage', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('cilium-may-2026-patch-wave', 'Cilium Ships Coordinated Patch Wave Across 1.17, 1.18, and 1.19', 'Cilium published v1.19.4, v1.18.10, and v1.17.16 on May 13, fixing IPsec packet drops during key rotation, ARP failures for LoadBalancer services, and a CiliumLocalRedirectPolicy edge case that could override an existing Service frontend.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cilium published patch releases for all three supported branches on May 13: v1.19.4, v1.18.10, and v1.17.16. No new CVEs were assigned in this wave, but the bug list is dominated by production-stability fixes worth tracking, especially for clusters using IPsec, the egress gateway, or LocalRedirectPolicies."}]},{"type":"heading","attrs":{"level":2,"id":"whats-fixed"},"content":[{"type":"text","text":"What''s fixed"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"IPsec packet drops during key rotation.","marks":[{"type":"bold"}]},{"type":"text","text":" Rolling restarts with key rotation could drop packets — fixed across the wave."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"WireGuard MTU clamping.","marks":[{"type":"bold"}]},{"type":"text","text":" MTU is now clamped to "},{"type":"text","text":"IPV6_MIN_MTU","marks":[{"type":"code"}]},{"type":"text","text":" (1280) to prevent packet loss in tunnel-plus-encryption scenarios."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ARP failures for LoadBalancer services.","marks":[{"type":"bold"}]},{"type":"text","text":" Caused by pointer reuse during BPF map iteration; this manifested as intermittent service unreachability."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CiliumLocalRedirectPolicy edge case.","marks":[{"type":"bold"}]},{"type":"text","text":" The "},{"type":"text","text":"addressMatcher","marks":[{"type":"code"}]},{"type":"text","text":" could override an existing Service''s frontend when its backend pods were not yet "},{"type":"text","text":"Ready","marks":[{"type":"code"}]},{"type":"text","text":". Patched."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"L7 LoadBalancer / Ingress drops on bridged kernels.","marks":[{"type":"bold"}]},{"type":"text","text":" Specific kernel/bridge combinations saw traffic drops; resolved."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SocketLB error codes.","marks":[{"type":"bold"}]},{"type":"text","text":" Returned incorrect codes when services lacked backends, breaking client retry logic that keyed on errno."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datapath reinitialization deadlock","marks":[{"type":"bold"}]},{"type":"text","text":" when triggered from the local API."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"notable-smaller-items"},"content":[{"type":"text","text":"Notable smaller items"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"EndpointSlices","marks":[{"type":"code"}]},{"type":"text","text":" are now filtered by the "},{"type":"text","text":"service-proxy-name","marks":[{"type":"code"}]},{"type":"text","text":" label at watch level, reducing apiserver load in clusters that segment proxies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"iptables masquerading respects longest-prefix-match via route sorting — fixes a subtle correctness issue when overlapping CIDRs are configured."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The SPIRE client is now configurable for "},{"type":"text","text":"ztunnel","marks":[{"type":"code"}]},{"type":"text","text":", useful for service-mesh integrations."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"x/net","marks":[{"type":"code"}]},{"type":"text","text":" was bumped to v0.53 and base images refreshed."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do"},"content":[{"type":"text","text":"What to do"}]},{"type":"paragraph","content":[{"type":"text","text":"If you run IPsec with periodic key rotation, or rely on LoadBalancer services on hosts where ARP behavior is sensitive, this patch wave is worth scheduling promptly. Operators on 1.18.0–1.18.5 should also confirm they''re past v1.18.6 if they ever ran WireGuard with the beta Node Encryption feature — that earlier fix addressed CVE-2026-26963 and is unrelated to this wave."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Cilium v1.19.4","marks":[{"type":"link","attrs":{"href":"https://github.com/cilium/cilium/releases/tag/v1.19.4","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"Cilium v1.18.10","marks":[{"type":"link","attrs":{"href":"https://github.com/cilium/cilium/releases/tag/v1.18.10","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"Cilium v1.17.16","marks":[{"type":"link","attrs":{"href":"https://github.com/cilium/cilium/releases/tag/v1.17.16","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 13, 2026."}]}]}', 1778630400000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('cilium-may-2026-patch-wave', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('cilium-may-2026-patch-wave', 'cilium', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('containerd-cve-2026-46680-runasnonroot-bypass', 'containerd patches a runAsNonRoot bypass across every supported branch', 'containerd v2.3.1, v2.2.4, v2.0.9, and v1.7.32 fix CVE-2026-46680, a moderate-severity flaw that lets a crafted image override a pod''s numeric runAsUser by exploiting integer overflow in OCI USER parsing.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The containerd maintainers shipped coordinated patches on May 20 — v2.3.1, v2.2.4, v2.0.9, and v1.7.32 — fixing CVE-2026-46680, a moderate-severity advisory that lets a crafted image bypass a pod''s "},{"type":"text","text":"runAsNonRoot","marks":[{"type":"code"}]},{"type":"text","text":" restriction."}]},{"type":"heading","attrs":{"level":2,"id":"what-the-advisory-covers"},"content":[{"type":"text","text":"What the advisory covers"}]},{"type":"paragraph","content":[{"type":"text","text":"GHSA-fqw6-gf59-qr4w describes numeric "},{"type":"text","text":"User","marks":[{"type":"code"}]},{"type":"text","text":" directives in OCI specs that exceed the 32-bit integer range. When the value falls outside that range, containerd parses it as a username instead, then resolves it against the image''s "},{"type":"text","text":"/etc/passwd","marks":[{"type":"code"}]},{"type":"text","text":". An image whose passwd file maps that string to UID 0 lands the container as root, even when the pod spec asked for a non-root numeric user. The advisory lists containerd v1.7.27+ and v2.0.4+ as affected."}]},{"type":"heading","attrs":{"level":2,"id":"other-notable-fixes"},"content":[{"type":"text","text":"Other notable fixes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"AF_ALG is now blocked in the default seccomp socket policy, removing a kernel crypto API path from container processes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The overlayfs "},{"type":"text","text":"rebase","marks":[{"type":"code"}]},{"type":"text","text":" capability is disabled when running in a user namespace, which had been breaking layer extraction."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The sandbox task API now handles non-runc runtimes correctly; task fields in Runc options are deprecated."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Metadata and mount plugin boltdb files now close cleanly on server shutdown."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The transfer plugin no longer errors out when EROFS differ is configured without "},{"type":"text","text":"mkfs.erofs","marks":[{"type":"code"}]},{"type":"text","text":" on the host."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"mitigations-short-of-upgrading"},"content":[{"type":"text","text":"Mitigations short of upgrading"}]},{"type":"paragraph","content":[{"type":"text","text":"The advisory lists restricting image imports to trusted sources, enforcing a numeric "},{"type":"text","text":"runAsUser","marks":[{"type":"code"}]},{"type":"text","text":" in Pod security contexts, or upgrading to Kubernetes 1.34+ — which validates "},{"type":"text","text":"runAsUser","marks":[{"type":"code"}]},{"type":"text","text":" independently of the runtime — as workarounds for clusters that cannot patch immediately. The 2.x branches also pick up Go 1.26.3 and bump the containerd API to v1.11.1."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"containerd security advisory GHSA-fqw6-gf59-qr4w","marks":[{"type":"link","attrs":{"href":"https://github.com/containerd/containerd/security/advisories/GHSA-fqw6-gf59-qr4w","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 20, 2026."}]}]}', 1779235200000, 1779368956000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('containerd-cve-2026-46680-runasnonroot-bypass', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('containerd-cve-2026-46680-runasnonroot-bypass', 'containerd', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('containerd-cve-2026-46680-runasnonroot-bypass', 'kubernetes', 1);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('crio-1-36-spdystream-cve-2026-35469', 'CRI-O 1.36 ships with CNI health monitoring; all supported branches patch a spdystream DoS', 'CRI-O 1.36.0 and patch releases for 1.35, 1.34, and 1.33 landed on May 5 with CVE-2026-35469 (CVSS 8.7) fixed across the board, alongside new CNI status polling and GOMAXPROCS injection.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CRI-O shipped "},{"type":"text","text":"v1.36.0","marks":[{"type":"link","attrs":{"href":"https://github.com/cri-o/cri-o/releases/tag/v1.36.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on May 5, 2026, the matching CRI for Kubernetes 1.36. Patch releases for the older supported branches — v1.35.3, v1.34.8, and v1.33.12 — went out the same day."}]},{"type":"heading","attrs":{"level":2,"id":"cve-2026-35469-across-every-supported-branch"},"content":[{"type":"text","text":"CVE-2026-35469 across every supported branch"}]},{"type":"paragraph","content":[{"type":"text","text":"Every release in the May 5 batch updates "},{"type":"text","text":"spdystream","marks":[{"type":"code"}]},{"type":"text","text":" from 0.5.0 to 0.5.1 to address "},{"type":"text","text":"CVE-2026-35469","marks":[{"type":"link","attrs":{"href":"https://nvd.nist.gov/vuln/detail/CVE-2026-35469","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", a denial-of-service flaw in the Go SPDY library used by CRI streaming endpoints. The SPDY/3 frame parser allocates memory based on attacker-controlled counts and lengths without bounds checking, and because header blocks are zlib-compressed a small on-the-wire payload can decompress into very large allocations. CVSS 4.0 score is 8.7 (HIGH). The Red Hat advisory lists kubelet, CRI-O, and kube-apiserver as affected components."}]},{"type":"heading","attrs":{"level":2,"id":"whats-new-in-136-itself"},"content":[{"type":"text","text":"What''s new in 1.36 itself"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CNI plugin health monitoring.","marks":[{"type":"bold"}]},{"type":"text","text":" CRI-O now continuously polls CNI plugins via the "},{"type":"text","text":"STATUS","marks":[{"type":"code"}]},{"type":"text","text":" verb and reports "},{"type":"text","text":"NetworkReady","marks":[{"type":"code"}]},{"type":"text","text":" accordingly, rather than discovering broken CNI only at pod-create time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"min_injected_gomaxprocs","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" config option.","marks":[{"type":"bold"}]},{"type":"text","text":" Lets operators set a floor for "},{"type":"text","text":"GOMAXPROCS","marks":[{"type":"code"}]},{"type":"text","text":" in every container CRI-O creates — useful when CPU limits don''t match the thread-count assumptions of Go or Java workloads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Streaming container methods.","marks":[{"type":"bold"}]},{"type":"text","text":" Implements "},{"type":"text","text":"StreamContainers","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"StreamContainerStats","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"StreamPodSandboxes","marks":[{"type":"code"}]},{"type":"text","text":", matching the newer streaming CRI surface."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"systemd + ","marks":[{"type":"bold"}]},{"type":"text","text":"hostUsers: false","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" regression fixed.","marks":[{"type":"bold"}]},{"type":"text","text":" A v1.35.0 regression that caused permission-denied failures for systemd containers with user namespaces is resolved."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fast-exit race.","marks":[{"type":"bold"}]},{"type":"text","text":" A race that reported "},{"type":"text","text":"exitCode 255","marks":[{"type":"code"}]},{"type":"text","text":" for containers that exited very quickly is fixed."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If you run CRI-O — including on the older 1.33–1.35 branches — patch level matters here regardless of whether you''ve consumed the matching Kubernetes patches."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"CRI-O v1.36.0 release notes","marks":[{"type":"link","attrs":{"href":"https://github.com/cri-o/cri-o/releases/tag/v1.36.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"CVE-2026-35469 (NVD)","marks":[{"type":"link","attrs":{"href":"https://nvd.nist.gov/vuln/detail/CVE-2026-35469","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"GHSA-pc3f-x583-g7j2","marks":[{"type":"link","attrs":{"href":"https://github.com/advisories/GHSA-pc3f-x583-g7j2","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 5, 2026"}]}]}', 1777939200000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('crio-1-36-spdystream-cve-2026-35469', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('crio-1-36-spdystream-cve-2026-35469', 'crio', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('crio-1-36-spdystream-cve-2026-35469', 'kubernetes', 1);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('dragonfly-native-huggingface-modelscope-protocols', 'Dragonfly Adds Native Hugging Face and ModelScope Protocols', 'Dragonfly''s dfget now supports hf:// and modelscope:// with auth and revision pinning. The upside is simpler model distribution and lower origin egress, but benchmark claims still need real cluster data.', '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"id":"what-happened"},"content":[{"type":"text","text":"What happened"}]},{"type":"paragraph","content":[{"type":"text","text":"Dragonfly added native Hugging Face and ModelScope support to "},{"type":"text","text":"dfget","marks":[{"type":"code"}]},{"type":"text","text":" via "},{"type":"text","text":"hf://","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"modelscope://","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"For platform teams, this removes a lot of custom model sync and cache glue."}]},{"type":"paragraph","content":[{"type":"text","text":"You can pull models directly with built-in auth, revision pinning, and recursive fetches."}]},{"type":"heading","attrs":{"level":2,"id":"why-it-matters"},"content":[{"type":"text","text":"Why it matters"}]},{"type":"paragraph","content":[{"type":"text","text":"On inference clusters, model pull is usually the cold-start bottleneck and one of the biggest avoidable egress costs."}]},{"type":"paragraph","content":[{"type":"text","text":"The traffic math is straightforward. A 130 GB model across 200 nodes is 26 TB if every node pulls from origin. With Dragonfly in front, origin should see roughly one full pull (~130 GB). That is the 99.5% claim."}]},{"type":"paragraph","content":[{"type":"text","text":"It also reduces lock-in to internal mirror pipelines and custom fetch services that become permanent maintenance debt."}]},{"type":"heading","attrs":{"level":2,"id":"how-it-looks"},"content":[{"type":"text","text":"How it looks"}]},{"type":"codeBlock","attrs":{"language":"sh","title":null,"meta":null},"content":[{"type":"text","text":"dfget hf://deepseek-ai/DeepSeek-R1/model.safetensors -O /models/DeepSeek-R1/model.safetensors\ndfget hf://owner/repo -O ./repo/ -r"}]},{"type":"paragraph","content":[{"type":"text","text":"ModelScope follows the same pattern with "},{"type":"text","text":"--ms-token","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"--ms-revision","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"The key behavior is piece-level sharing. Seed peers can upload chunks before the full model download completes, so pulls become parallel instead of serialized."}]},{"type":"heading","attrs":{"level":2,"id":"proven-vs-unproven"},"content":[{"type":"text","text":"Proven vs unproven"}]},{"type":"paragraph","content":[{"type":"text","text":"Proven:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Native "},{"type":"text","text":"hf://","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"modelscope://","marks":[{"type":"code"}]},{"type":"text","text":" support in "},{"type":"text","text":"dfget","marks":[{"type":"code"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cleaner integration path than custom mirror jobs"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Clear origin-traffic reduction math"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Unproven (in public data so far):"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"p50/p95 model-ready startup time at scale"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"cross-AZ and cross-region behavior"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"token handling guidance that avoids secrets in shell history"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"failure behavior when origin is slow or rate-limited"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"end-to-end security posture for private model pulls"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do-next"},"content":[{"type":"text","text":"What to do next"}]},{"type":"paragraph","content":[{"type":"text","text":"If you currently mirror Hugging Face or ModelScope into internal storage, run a controlled pilot and compare:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"cold-start time per pod"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"origin egress"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"east-west network load"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"operational complexity (how much code/config you can delete)"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"If the numbers hold, delete the mirror pipeline."}]}]}', 1775606400000, 1775642831000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('dragonfly-native-huggingface-modelscope-protocols', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('dragonfly-native-huggingface-modelscope-protocols', 'dragonfly', 0);
