INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('etcd-3-7-beta-v2-api-removed', 'etcd cuts first 3.7 beta and removes the v2 API', 'etcd v3.7.0-beta.0 deletes client/v2, v2discovery, and the v2 request path, adds Unix socket endpoints and FastLeaseKeepAlive, and reports up to 2x faster lease, user, and role operations.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"etcd published v3.7.0-beta.0 on May 19, the first beta on the 3.7 line. The cleanup is the headline: the v2 API and discovery code are gone."}]},{"type":"heading","attrs":{"level":2,"id":"the-v2-era-is-finally-over"},"content":[{"type":"text","text":"The v2 era is finally over"}]},{"type":"paragraph","content":[{"type":"text","text":"client/v2","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"v2discovery","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"apply_v2.go","marks":[{"type":"code"}]},{"type":"text","text":", and the v2 request path have all been removed, along with deprecated experimental flags. The v2 store has been off by default for years and unsupported for newer features, but anything still talking to it has to be on v3 before 3.7 ships GA."}]},{"type":"heading","attrs":{"level":2,"id":"server-changes"},"content":[{"type":"text","text":"Server changes"}]},{"type":"paragraph","content":[{"type":"text","text":"The 3.7 line adds Unix socket endpoint support, FastLeaseKeepAlive that skips the applied-index wait on lease renewal, and a scheduler change that prioritizes "},{"type":"text","text":"LeaseRevoke","marks":[{"type":"code"}]},{"type":"text","text":" requests during overload so leases expire on time. Lease and user/role operations are reported up to 2x faster. AuthStatus can now be retrieved without an authenticated session, and clientv3 supports JWT configuration directly."}]},{"type":"heading","attrs":{"level":2,"id":"operator-facing-changes"},"content":[{"type":"text","text":"Operator-facing changes"}]},{"type":"paragraph","content":[{"type":"text","text":"etcdctl","marks":[{"type":"code"}]},{"type":"text","text":" global flags are hidden from the default help to reduce noise, and every "},{"type":"text","text":"etcdutl","marks":[{"type":"code"}]},{"type":"text","text":" command picks up a timeout flag for file lock acquisition. New metrics include "},{"type":"text","text":"etcd_server_request_duration_seconds","marks":[{"type":"code"}]},{"type":"text","text":" and watch send-loop counters. Binaries are now built with Go 1.26."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a beta — not for production — but the v2 removal is the part to plan for now."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"etcd v3.7.0-beta.0","marks":[{"type":"link","attrs":{"href":"https://github.com/etcd-io/etcd/releases/tag/v3.7.0-beta.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 19, 2026."}]}]}', 1779235200000, 1779276044000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('etcd-3-7-beta-v2-api-removed', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('etcd-3-7-beta-v2-api-removed', 'etcd', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('flux-2-8-8-go-git-cves-helm-controller-memory', 'Flux 2.8.8 patches two go-git CVEs and stops helm-controller memory growth', 'Flux v2.8.8 picks up go-git v5.19.1 to address CVE-2026-45571 and CVE-2026-45570, fixes an unbounded memory leak in helm-controller''s Kubernetes client transport, and adds GCP sovereign cloud artifact registry support.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flux v2.8.8 shipped on May 20. It is a patch release, but the helm-controller memory fix and two go-git CVEs are reasons to pick it up."}]},{"type":"heading","attrs":{"level":2,"id":"go-git-cves"},"content":[{"type":"text","text":"go-git CVEs"}]},{"type":"paragraph","content":[{"type":"text","text":"The release bumps go-git to v5.19.1 to address CVE-2026-45571 and CVE-2026-45570. Anything using source-controller''s Git fetch path picks up the fix."}]},{"type":"heading","attrs":{"level":2,"id":"helm-controller-memory-leak"},"content":[{"type":"text","text":"helm-controller memory leak"}]},{"type":"paragraph","content":[{"type":"text","text":"The notes flag \"unbounded memory growth caused by a Kubernetes client transport retry wrapper accumulating on every reconcile.\" Long-lived helm-controller pods reconciling many Helm releases have been the most exposed to this; the wrapper is now cleaned up between reconciles."}]},{"type":"heading","attrs":{"level":2,"id":"gcp-sovereign-cloud-artifact-registries"},"content":[{"type":"text","text":"GCP sovereign cloud artifact registries"}]},{"type":"paragraph","content":[{"type":"text","text":"Source-controller and image-reflector-controller now support GCP sovereign cloud artifact registries — a real gap for operators running on sovereign-region GKE who had been pointing pipelines at the standard "},{"type":"text","text":"pkg.dev","marks":[{"type":"code"}]},{"type":"text","text":" endpoints."}]},{"type":"heading","attrs":{"level":2,"id":"other-patches-worth-noting"},"content":[{"type":"text","text":"Other patches worth noting"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"HTTP timeout for artifact fetching is now configurable, so reconciles cannot block indefinitely on a hung remote."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Helm release names longer than 53 characters no longer break the Helm test action."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Charts whose "},{"type":"text","text":"crds/","marks":[{"type":"code"}]},{"type":"text","text":" directories contain non-CRD objects are no longer force-applied alongside CRDs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"OCIRepository tags now encode Helm semver build metadata correctly."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Helm moves back to upstream v4.2.0 and the controllers ship against Kubernetes 1.36.1. No breaking changes are flagged for the v2.8.x upgrade path."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Flux v2.8.8","marks":[{"type":"link","attrs":{"href":"https://github.com/fluxcd/flux2/releases/tag/v2.8.8","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 20, 2026."}]}]}', 1779235200000, 1779368956000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('flux-2-8-8-go-git-cves-helm-controller-memory', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('flux-2-8-8-go-git-cves-helm-controller-memory', 'fluxcd', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('helm-4-2-3-21-v3-eol-warning', 'Helm 4.2 lands; Helm 3.21 ships with an explicit end-of-life warning', 'Helm v4.2.0 and v3.21.0 both released on May 14, with the v3 release notes now stating that the v3 line is approaching end-of-life — a planning trigger for the long tail of clusters still on v3 charts.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Helm shipped "},{"type":"text","text":"v4.2.0","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v4.2.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" and "},{"type":"text","text":"v3.21.0","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v3.21.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" on May 14, 2026. The notable change isn''t in the changelog — it''s the warning at the top of the v3.21.0 notes that Helm v3 is approaching end-of-life and that operators should plan their migration to v4."}]},{"type":"heading","attrs":{"level":2,"id":"whats-in-v42"},"content":[{"type":"text","text":"What''s in v4.2"}]},{"type":"paragraph","content":[{"type":"text","text":"The release continues to track Kubernetes upstream tightly: client libraries are bumped to v1.36, Go is bumped to 1.26, and controller-runtime to v0.24. The headline functional changes:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new "},{"type":"text","text":"mustToToml","marks":[{"type":"code"}]},{"type":"text","text":" template function for charts that need TOML rendering without dropping back to raw strings."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"--dry-run=server","marks":[{"type":"code"}]},{"type":"text","text":" now honours "},{"type":"text","text":"generateName:","marks":[{"type":"code"}]},{"type":"text","text":" instead of erroring on names that the apiserver would assign."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The build switches to goreleaser; binaries are now produced for "},{"type":"text","text":"loong64","marks":[{"type":"code"}]},{"type":"text","text":" (LoongArch)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Multiple fixes for post-renderers — hooks no longer collide with templates, and YAML separator parsing and Windows line-ending handling are corrected."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"--hide-notes","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"--render-subchart-notes","marks":[{"type":"code"}]},{"type":"text","text":" flags are deprecated."}]},{"type":"heading","attrs":{"level":2,"id":"whats-in-v321"},"content":[{"type":"text","text":"What''s in v3.21"}]},{"type":"paragraph","content":[{"type":"text","text":"The v3 line is in maintenance: this release upgrades "},{"type":"text","text":"opentelemetry","marks":[{"type":"code"}]},{"type":"text","text":" packages to pick up patched CVEs and corrects a chart-path bug. No new functional surface."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-matters-now"},"content":[{"type":"text","text":"Why this matters now"}]},{"type":"paragraph","content":[{"type":"text","text":"Helm v4 has been GA since November 12, 2025, but most production clusters still distribute v3 charts. The explicit \"approaching end-of-life\" language in a release-notes header — rather than a separate deprecation announcement — is the planning trigger: vendors will start dropping v3-only charts, and chart authors will need to validate against v4''s stricter template engine."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Helm v4.2.0","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v4.2.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"Helm v3.21.0","marks":[{"type":"link","attrs":{"href":"https://github.com/helm/helm/releases/tag/v3.21.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 14, 2026"}]}]}', 1778716800000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('helm-4-2-3-21-v3-eol-warning', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('helm-4-2-3-21-v3-eol-warning', 'helm', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('istio-ambient-multicluster-inference-extension', 'Istio Ships Ambient Multicluster Beta and Gateway API Inference Extension', 'Istio''s ambient mode gains multicluster support in beta with sidecar-free cross-cluster routing, and integrates the Gateway API Inference Extension for model-aware traffic management.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Istio dropped two big releases at KubeCon + CloudNativeCon Europe 2026: Ambient Multicluster in beta and the Gateway API Inference Extension in beta."}]},{"type":"heading","attrs":{"level":2,"id":"ambient-multicluster-beta"},"content":[{"type":"text","text":"Ambient Multicluster Beta"}]},{"type":"paragraph","content":[{"type":"text","text":"Istio''s ambient mode now supports multicluster deployments, giving you cross-cluster traffic routing without sidecars. The key capabilities include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dynamic cross-cluster failover where requests automatically redirect to another cluster when a service failure is detected"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ztunnel-to-ztunnel mTLS for zero-trust security across cluster boundaries"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Simplified operational model compared to sidecar-based multicluster deployments"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This eliminates the sidecar tax for cross-cluster traffic, a pain point that''s plagued multi-cluster Kubernetes teams for years."}]},{"type":"heading","attrs":{"level":2,"id":"gateway-api-inference-extension"},"content":[{"type":"text","text":"Gateway API Inference Extension"}]},{"type":"paragraph","content":[{"type":"text","text":"Istio also integrated the Gateway API Inference Extension, which effectively turns any Istio gateway into an inference gateway. The extension adds:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Model-aware routing","marks":[{"type":"bold"}]},{"type":"text","text":" so you can route requests based on the target model"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Per-request criticality levels","marks":[{"type":"bold"}]},{"type":"text","text":" to prioritize inference requests"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Load balancing based on real-time model server metrics","marks":[{"type":"bold"}]},{"type":"text","text":" for better GPU utilization without manual tuning"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This means platform teams can use their existing Istio service mesh infrastructure to route to LLM backends with model-aware intelligence, without deploying a separate inference proxy."}]},{"type":"heading","attrs":{"level":2,"id":"the-bigger-picture"},"content":[{"type":"text","text":"The Bigger Picture"}]},{"type":"paragraph","content":[{"type":"text","text":"Ambient multicluster removes the sidecar overhead for cross-cluster networking while keeping zero-trust security intact. The inference extension is equally useful: instead of bolting on a separate inference gateway, your existing mesh handles model routing natively. Two fewer things to deploy and operate."}]}]}', 1774396800000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('istio-ambient-multicluster-inference-extension', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('istio-ambient-multicluster-inference-extension', 'kubernetes', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('istio-ambient-multicluster-inference-extension', 'istio', 1);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-dra-drivers-features-beta', 'Kubernetes 1.36 graduates DRA prioritized list to GA and pushes five device-control features to beta', 'On the heels of DRA graduating to GA in v1.36, the May 7 follow-up details one new stable feature — prioritized list — and five betas covering partitionable devices, device taints, device binding conditions, resource health, and extended-resource integration. ResourceClaims also work with the new PodGroup API.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.36 shipped Dynamic Resource Allocation to GA on April 22. The follow-up blog post on May 7 details one feature graduating to GA inside DRA itself and five betas that fill in operational gaps for accelerator scheduling."}]},{"type":"heading","attrs":{"level":2,"id":"what-graduated"},"content":[{"type":"text","text":"What graduated"}]},{"type":"paragraph","content":[{"type":"text","text":"Prioritized list (GA).","marks":[{"type":"bold"}]},{"type":"text","text":" A ResourceClaim can declare ordered preferences for device selection. The example from the post: \"H100, but if none are available, fall back to an A100.\" Scheduling honors the ordering when devices are heterogeneous across the cluster — useful in any fleet running mixed accelerator generations."}]},{"type":"heading","attrs":{"level":2,"id":"what-hit-beta"},"content":[{"type":"text","text":"What hit beta"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Partitionable devices.","marks":[{"type":"bold"}]},{"type":"text","text":" Define logical partitions of physical hardware. The intended pattern is Multi-Instance GPU style allocation, with the scheduler tracking partitions as first-class allocatable units."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Device taints.","marks":[{"type":"bold"}]},{"type":"text","text":" Apply taints directly to DRA devices, parallel to node taints. Faulty hardware stops getting allocated without ripping it out of the resource pool."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Device binding conditions.","marks":[{"type":"bold"}]},{"type":"text","text":" Block a Pod''s scheduling commitment on an external preparation step, so pods don''t fire before fabric setup or out-of-band device prep completes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Resource health status.","marks":[{"type":"bold"}]},{"type":"text","text":" Pod status surfaces device health with human-readable messages instead of forcing operators into driver logs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Extended resource support.","marks":[{"type":"bold"}]},{"type":"text","text":" Pods can request DRA-managed resources through the familiar extended-resource API on containers, easing migration for clusters that haven''t adopted ResourceClaim semantics yet."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"dra-in-podgroups"},"content":[{"type":"text","text":"DRA in PodGroups"}]},{"type":"paragraph","content":[{"type":"text","text":"ResourceClaims now work with the new PodGroup API that also landed in 1.36. Gang-scheduled jobs — the standard AI training pattern — can request DRA-managed accelerators through a single shared claim rather than stitching per-pod requests together at submit time."}]},{"type":"heading","attrs":{"level":2,"id":"driver-ecosystem"},"content":[{"type":"text","text":"Driver ecosystem"}]},{"type":"paragraph","content":[{"type":"text","text":"The post explicitly notes the driver ecosystem expanding past GPU accelerators to networking and other hardware classes. NVIDIA''s donation of the GPU DRA driver to the CNCF in March feeds into the same pipeline."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: More Drivers, New Features, and the Next Era of DRA","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/07/kubernetes-v1-36-dra-136-updates/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 7, 2026."}]}]}', 1778112000000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-dra-drivers-features-beta', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-dra-drivers-features-beta', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-pod-level-resource-managers-alpha', 'Kubernetes 1.36 introduces pod-level CPU, memory, and topology managers in alpha', 'The kubelet''s CPU, memory, and topology managers extend to pod scope behind the PodLevelResourceManagers and PodLevelResources feature gates. Performance-critical containers keep NUMA alignment while lightweight sidecars share a pod-level budget rather than burning dedicated cores.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.36 ships pod-level resource managers in alpha. The kubelet''s CPU, memory, and topology managers — historically per-container — now operate at the pod boundary. Two feature gates need to be on: "},{"type":"text","text":"PodLevelResourceManagers","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"PodLevelResources","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"what-changes"},"content":[{"type":"text","text":"What changes"}]},{"type":"paragraph","content":[{"type":"text","text":"A pod can declare resources at "},{"type":"text","text":".spec.resources","marks":[{"type":"code"}]},{"type":"text","text":", and the kubelet uses that allocation as the budget and NUMA-alignment scope for the entire pod. Containers can still set their own requests and limits; any unused pod-level budget becomes a shared pool that lightweight sidecars draw from."}]},{"type":"paragraph","content":[{"type":"text","text":"Example: a pod with "},{"type":"text","text":"cpu: 8","marks":[{"type":"code"}]},{"type":"text","text":" at pod level and a primary container at "},{"type":"text","text":"cpu: 6","marks":[{"type":"code"}]},{"type":"text","text":" leaves a 2-CPU pool that metrics exporters, log shippers, or service-mesh sidecars share — no per-sidecar dedicated allocation required."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-exists"},"content":[{"type":"text","text":"Why this exists"}]},{"type":"paragraph","content":[{"type":"text","text":"The status quo forces a choice between Guaranteed QoS on the main workload (and over-allocating cores per sidecar) or Burstable everywhere (and losing NUMA pinning entirely). Pod-level resources keep the performance-critical container on dedicated, NUMA-aligned cores while collapsing sidecar overhead into the leftover budget on the same NUMA node."}]},{"type":"paragraph","content":[{"type":"text","text":"The post calls out two concrete patterns: latency-sensitive databases with backup agents and metrics exporters, and GPU-accelerated training pods with service-mesh sidecars. Both are workloads where mixing per-container Guaranteed pods has been awkward."}]},{"type":"heading","attrs":{"level":2,"id":"status"},"content":[{"type":"text","text":"Status"}]},{"type":"paragraph","content":[{"type":"text","text":"Alpha, off by default. The Topology Manager scope "},{"type":"text","text":"pod","marks":[{"type":"code"}]},{"type":"text","text":" is required to get cross-container NUMA alignment under this model."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: Pod-Level Resource Managers (Alpha)","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/01/kubernetes-v1-36-feature-pod-level-resource-managers-alpha/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 1, 2026."}]}]}', 1777593600000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-pod-level-resource-managers-alpha', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-pod-level-resource-managers-alpha', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-podgroup-workload-scheduling', 'Kubernetes 1.36 splits Workload and PodGroup APIs for batch and AI scheduling', 'Kubernetes v1.36 introduces a new PodGroup API alongside the Workload API in scheduling.k8s.io/v1alpha2, separating static templates from runtime state and unlocking DRA for gang-scheduled workloads.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.36 ships the second iteration of workload-aware scheduling, announced on the project blog May 13, 2026. The shape of the API has changed since v1.35."}]},{"type":"heading","attrs":{"level":2,"id":"a-clean-split"},"content":[{"type":"text","text":"A clean split"}]},{"type":"paragraph","content":[{"type":"text","text":"v1.35","marks":[{"type":"code"}]},{"type":"text","text":" introduced the Workload API and basic gang scheduling on a Pod-based framework. "},{"type":"text","text":"v1.36","marks":[{"type":"code"}]},{"type":"text","text":" moves both APIs to "},{"type":"text","text":"scheduling.k8s.io/v1alpha2","marks":[{"type":"code"}]},{"type":"text","text":" and splits concerns: the Workload acts as a static template containing "},{"type":"text","text":"podGroupTemplates","marks":[{"type":"code"}]},{"type":"text","text":", while the new PodGroup object carries the runtime "},{"type":"text","text":"schedulingPolicy","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"status.conditions","marks":[{"type":"code"}]},{"type":"text","text":". The Pod field "},{"type":"text","text":"workloadRef","marks":[{"type":"code"}]},{"type":"text","text":" is replaced with "},{"type":"text","text":"schedulingGroup","marks":[{"type":"code"}]},{"type":"text","text":", which references a PodGroup directly so the scheduler can read scheduling state without parsing the Workload."}]},{"type":"heading","attrs":{"level":2,"id":"what-landed-under-the-new-shape"},"content":[{"type":"text","text":"What landed under the new shape"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new PodGroup scheduling cycle in "},{"type":"text","text":"kube-scheduler","marks":[{"type":"code"}]},{"type":"text","text":" for atomic workload processing"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First iterations of topology-aware scheduling and workload-aware preemption"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ResourceClaim","marks":[{"type":"code"}]},{"type":"text","text":" support for workloads, extending Dynamic Resource Allocation to entire PodGroups"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The first phase of integration between the Job controller and the new API"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"still-alpha"},"content":[{"type":"text","text":"Still alpha"}]},{"type":"paragraph","content":[{"type":"text","text":"Everything in "},{"type":"text","text":"v1alpha2","marks":[{"type":"code"}]},{"type":"text","text":" is alpha. Don''t migrate production gang-scheduling off Kueue, Volcano, or YuniKorn yet. But the upstream foundations for the same patterns now exist, and the API shape will keep moving until beta."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: Advancing Workload-Aware Scheduling","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/13/kubernetes-v1-36-advancing-workload-aware-scheduling/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 13, 2026"}]}]}', 1778630400000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-podgroup-workload-scheduling', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-podgroup-workload-scheduling', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-psi-metrics-ga', 'Kubernetes 1.36 graduates PSI metrics to GA', 'Pressure Stall Information metrics are now GA at node, pod, and container levels in Kubernetes v1.36, giving operators a kernel-grade signal for resource contention without out-of-band tooling.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pressure Stall Information (PSI) metrics reached general availability in Kubernetes v1.36, with the announcement landing on the project blog on May 12, 2026."}]},{"type":"heading","attrs":{"level":2,"id":"what-psi-actually-measures"},"content":[{"type":"text","text":"What PSI actually measures"}]},{"type":"paragraph","content":[{"type":"text","text":"PSI surfaces percentages of time tasks are stalled on CPU, memory, or I/O — not how much resource was consumed, but how much time was lost waiting. The kernel has exposed this since 2018; Kubernetes now wires it through the kubelet at node, pod, and container granularity. Each metric ships as a cumulative total plus moving averages over 10s, 60s, and 300s windows, distinguishing transient spikes from sustained contention."}]},{"type":"heading","attrs":{"level":2,"id":"production-overhead"},"content":[{"type":"text","text":"Production overhead"}]},{"type":"paragraph","content":[{"type":"text","text":"SIG Node measured kubelet collection overhead consistently below 2.5% of total node capacity, with kernel-level tracking between 0.925% and 3.125%, validated under high-density workloads of 80+ pods."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-matters"},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"PSI gives you a first-class upstream answer to \"is this pod actually being starved?\" without resorting to eBPF tooling or vendor agents. If you''ve been reading CPU throttling counters to debug noisy-neighbor problems, you now have a directly applicable signal."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: PSI Metrics for Kubernetes Graduates to GA","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/12/kubernetes-v1-36-psi-metrics-ga/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 12, 2026"}]}]}', 1778544000000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-psi-metrics-ga', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-psi-metrics-ga', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-server-side-sharded-list-watch-alpha', 'Kubernetes 1.36 lands server-side sharded list and watch in alpha', 'KEP-5866 ships in v1.36 with a new shardSelector field on ListOptions, moving event filtering from clients to the API server. Horizontally sharded controllers no longer pay for the full stream of deserialization on objects they don''t own.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KEP-5866 landed in Kubernetes v1.36 as an alpha. The feature moves event filtering from clients into the API server for the common case where a controller is sharded horizontally across replicas."}]},{"type":"heading","attrs":{"level":2,"id":"the-cost-being-paid-today"},"content":[{"type":"text","text":"The cost being paid today"}]},{"type":"paragraph","content":[{"type":"text","text":"When N replicas of a controller each watch the same high-cardinality resource — Pods is the canonical case — the API server fans the full event stream to each replica. Every replica deserializes payloads it then discards. Network bandwidth scales with replica count rather than with shard size, and the CPU spent on deserializing discarded objects is pure waste."}]},{"type":"heading","attrs":{"level":2,"id":"the-new-path"},"content":[{"type":"text","text":"The new path"}]},{"type":"paragraph","content":[{"type":"text","text":"The alpha adds a "},{"type":"text","text":"shardSelector","marks":[{"type":"code"}]},{"type":"text","text":" field to "},{"type":"text","text":"ListOptions","marks":[{"type":"code"}]},{"type":"text","text":". Clients pass a deterministic expression — currently a 64-bit FNV-1a hash over "},{"type":"text","text":"metadata.uid","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"metadata.namespace","marks":[{"type":"code"}]},{"type":"text","text":" — that the API server evaluates before emitting events. A two-shard split on UID looks like:"}]},{"type":"codeBlock","attrs":{"language":null,"title":null,"meta":null},"content":[{"type":"text","text":"shardRange(object.metadata.uid, ''0x0000000000000000'', ''0x8000000000000000'')"}]},{"type":"paragraph","content":[{"type":"text","text":"The Go shared informer factory accepts the selector via "},{"type":"text","text":"WithTweakListOptions","marks":[{"type":"code"}]},{"type":"text","text":", so adoption is a one-line change for controllers already using the shared informer pattern. List responses include a "},{"type":"text","text":"shardInfo","marks":[{"type":"code"}]},{"type":"text","text":" field that echoes back the applied selector, so clients can verify the server actually honored it."}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do-with-this"},"content":[{"type":"text","text":"What to do with this"}]},{"type":"paragraph","content":[{"type":"text","text":"Alpha status means it ships behind a feature gate. Treat this as 1.37 planning material if you operate API servers under load from sharded controllers, and as the upstream answer to the long-standing question: why does scaling controller replicas not reduce apiserver egress?"}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: Server-Side Sharded List and Watch","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/06/kubernetes-v1-36-server-side-sharded-list-and-watch/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 6, 2026."}]}]}', 1778025600000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-server-side-sharded-list-watch-alpha', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-server-side-sharded-list-watch-alpha', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-service-externalips-deprecation', 'Kubernetes 1.36 formally deprecates Service externalIPs', 'The .spec.externalIPs field on Service objects is formally deprecated in Kubernetes v1.36, with kube-proxy implementation slated for removal in a future minor release. Driven by CVE-2020-8554.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":".spec.externalIPs","marks":[{"type":"code"}]},{"type":"text","text":" field on Kubernetes Service objects is formally deprecated in v1.36, per the project blog post on May 14, 2026. Implementation removal from "},{"type":"text","text":"kube-proxy","marks":[{"type":"code"}]},{"type":"text","text":" is planned for a future minor release, and conformance criteria will eventually require implementations not to support it."}]},{"type":"heading","attrs":{"level":2,"id":"why-its-going"},"content":[{"type":"text","text":"Why it''s going"}]},{"type":"paragraph","content":[{"type":"text","text":"The deprecation is security-driven. "},{"type":"text","text":"CVE-2020-8554","marks":[{"type":"link","attrs":{"href":"https://www.cvedetails.com/cve/CVE-2020-8554/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" showed that any user with permission to create Services could intercept arbitrary external traffic by claiming an IP. The API assumes all cluster users are fully trusted, which has not matched real deployments for years. Kubernetes has been recommending disabling "},{"type":"text","text":"externalIPs","marks":[{"type":"code"}]},{"type":"text","text":" since v1.21."}]},{"type":"heading","attrs":{"level":2,"id":"migration-paths"},"content":[{"type":"text","text":"Migration paths"}]},{"type":"paragraph","content":[{"type":"text","text":"The blog post calls out three replacements:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LoadBalancer Services","marks":[{"type":"bold"}]},{"type":"text","text":" with manually managed IPs (simplest, least defensive)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MetalLB","marks":[{"type":"bold"}]},{"type":"text","text":" for bare-metal clusters needing real load-balancer semantics"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ingress controllers","marks":[{"type":"bold"}]},{"type":"text","text":" for HTTP/HTTPS traffic"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This deprecation does "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" affect the Node API''s "},{"type":"text","text":".status.addresses","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"ExternalIP","marks":[{"type":"code"}]},{"type":"text","text":" entries or the "},{"type":"text","text":"EXTERNAL-IP","marks":[{"type":"code"}]},{"type":"text","text":" column kubectl prints for LoadBalancer Services. Only the "},{"type":"text","text":"Service.spec.externalIPs","marks":[{"type":"code"}]},{"type":"text","text":" field is being removed."}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do"},"content":[{"type":"text","text":"What to do"}]},{"type":"paragraph","content":[{"type":"text","text":"Audit your clusters for "},{"type":"text","text":"Service.spec.externalIPs","marks":[{"type":"code"}]},{"type":"text","text":" usage now. Some clusters have carried this configuration silently since the 1.x era, and removal is no longer hypothetical."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes v1.36: Deprecation and removal of Service ExternalIPs","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/blog/2026/05/14/kubernetes-v1-36-deprecation-and-removal-of-service-externalips/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 14, 2026"}]}]}', 1778716800000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-service-externalips-deprecation', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-service-externalips-deprecation', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-1-36-sneak-peek', 'Kubernetes 1.36 Sneak Peek: DRA Goes GA, Ingress-NGINX Retires, HPA Scales to Zero', 'Kubernetes v1.36, releasing April 22, finalizes DRA to GA, graduates User Namespaces, enables HPA scale-to-zero by default, and formally retires Ingress-NGINX.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes v1.36 drops on April 22, 2026. It''s a big one. Several features that have been cooking for years are finally landing, and one major deprecation will force migration plans."}]},{"type":"heading","attrs":{"level":2,"id":"dra-goes-ga"},"content":[{"type":"text","text":"DRA Goes GA"}]},{"type":"paragraph","content":[{"type":"text","text":"Four Dynamic Resource Allocation (DRA) enhancements are graduating to GA. After years of development, hardware-aware scheduling is now a first-class, production-ready feature in upstream Kubernetes. GPUs and other accelerators are finally manageable through standard Kubernetes APIs. No more relying on vendor-specific device plugins alone."}]},{"type":"heading","attrs":{"level":2,"id":"ingress-nginx-formally-retired"},"content":[{"type":"text","text":"Ingress-NGINX Formally Retired"}]},{"type":"paragraph","content":[{"type":"text","text":"Kubernetes SIG Network and the Security Response Committee have formally retired the Ingress-NGINX controller as of March 24, 2026. There will be no further releases, bugfixes, or security updates. Existing deployments continue to function and artifacts remain available, but this cements Gateway API as the standard ingress path going forward."}]},{"type":"heading","attrs":{"level":2,"id":"hpa-scale-to-zero-enabled-by-default"},"content":[{"type":"text","text":"HPA Scale-to-Zero Enabled by Default"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"HPAScaleToZero","marks":[{"type":"code"}]},{"type":"text","text":" feature gate, which has been sitting in alpha since Kubernetes v1.16, is now enabled by default. The Horizontal Pod Autoscaler can finally scale workloads down to zero replicas without additional configuration."}]},{"type":"heading","attrs":{"level":2,"id":"additional-highlights"},"content":[{"type":"text","text":"Additional Highlights"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"User Namespaces","marks":[{"type":"bold"}]},{"type":"text","text":" graduate to stable, providing better pod isolation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mutating Admission Policies","marks":[{"type":"bold"}]},{"type":"text","text":" graduate to stable"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"gitRepo volume plugin","marks":[{"type":"bold"}]},{"type":"text","text":" is permanently disabled with no opt-back-in"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"externalIPs","marks":[{"type":"bold"}]},{"type":"text","text":" field in Service spec is being deprecated, with full removal planned for v1.43"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"18 enhancements moving to stable in total"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Still on Ingress-NGINX? Start planning your Gateway API migration now. HPA scale-to-zero landing as default changes the economics of event-driven and batch workloads. And DRA going GA means hardware-aware scheduling is production-ready upstream, not a vendor add-on."}]}]}', 1774828800000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-1-36-sneak-peek', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-1-36-sneak-peek', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubernetes-may-2026-patch-wave', 'Kubernetes Ships May Patch Wave Across 1.33–1.36, Fixes IPv6 ServiceCIDR Allocation Bug', 'Kubernetes 1.36.1, 1.35.5, 1.34.8, and 1.33.12 landed on the May 12 cherry-pick window. No CVEs, but a real correctness bug — services getting IPv6 addresses outside their allocated CIDR — is among the fixes.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubernetes shipped its scheduled May patch wave: v1.36.1, v1.35.5, v1.34.8, and v1.33.12, all built off the May 8 cherry-pick deadline with target dates of May 12–13. No CVEs were rolled in this cycle, but the v1.34.8 changelog includes a handful of fixes that production operators should read before skipping the upgrade."}]},{"type":"heading","attrs":{"level":2,"id":"notable-fixes"},"content":[{"type":"text","text":"Notable fixes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"IPv6 ServiceCIDR allocation correctness (","marks":[{"type":"bold"}]},{"type":"text","text":"#138385","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/pull/138385","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}]},{"type":"text","text":").","marks":[{"type":"bold"}]},{"type":"text","text":" A bug allowed 64-bit IPv6 ServiceCIDRs to allocate addresses outside the configured subnet range. If you run dual-stack or IPv6-only services, validate your allocations after upgrading."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scheduler in-flight queue cleanup (","marks":[{"type":"bold"}]},{"type":"text","text":"#138435","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/pull/138435","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}]},{"type":"text","text":").","marks":[{"type":"bold"}]},{"type":"text","text":" Stale state could persist after failed scheduling attempts, with cascading effects on subsequent decisions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kube-proxy large-cluster sync (","marks":[{"type":"bold"}]},{"type":"text","text":"#138637","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/pull/138637","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}]},{"type":"text","text":").","marks":[{"type":"bold"}]},{"type":"text","text":" Full-sync was being skipped under \"large cluster mode\" in cases where it shouldn''t have been."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Windows HNS endpoint cleanup (","marks":[{"type":"bold"}]},{"type":"text","text":"#138601","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/pull/138601","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}]},{"type":"text","text":").","marks":[{"type":"bold"}]},{"type":"text","text":" Addresses DNS timeouts on L2Bridge networks — a long-standing pain point for Windows nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Kubeadm and kubelet fixes (","marks":[{"type":"bold"}]},{"type":"text","text":"#138685","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/pull/138685","target":null,"rel":null,"class":null,"title":null}},{"type":"bold"}]},{"type":"text","text":" and others).","marks":[{"type":"bold"}]},{"type":"text","text":" Better handling of delayed load balancers during init, etcd cluster status checks, LocalAPIEndpoint defaulting, and pod-startup SLI metric accuracy."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"support-context"},"content":[{"type":"text","text":"Support context"}]},{"type":"paragraph","content":[{"type":"text","text":"v1.34 enters maintenance mode on August 27, 2026, with end-of-life on October 27. Operators still on v1.33 should be planning their move; the 1.33.12 patch is a continuity release rather than a destination."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Kubernetes patch release schedule","marks":[{"type":"link","attrs":{"href":"https://kubernetes.io/releases/patch-releases/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"CHANGELOG-1.34","marks":[{"type":"link","attrs":{"href":"https://github.com/kubernetes/kubernetes/blob/master/CHANGELOG/CHANGELOG-1.34.md","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 12–13, 2026."}]}]}', 1778544000000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubernetes-may-2026-patch-wave', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('kubernetes-may-2026-patch-wave', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kubevirt-1-8-hypervisor-abstraction', 'KubeVirt v1.8: Hypervisor Abstraction Layer, Confidential VMs, and the Push Toward CNCF Graduation', 'KubeVirt v1.8 introduces a hypervisor abstraction layer decoupling it from KVM, Intel TDX attestation for confidential VMs, and PCIe NUMA topology awareness for near-native GPU performance.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"KubeVirt v1.8 landed at KubeCon Europe 2026 with three features that change how the project fits into the broader cloud native stack. The project is actively pushing toward CNCF graduation."}]},{"type":"heading","attrs":{"level":2,"id":"hypervisor-abstraction-layer"},"content":[{"type":"text","text":"Hypervisor Abstraction Layer"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the big one. A new Hypervisor Abstraction Layer decouples KubeVirt from KVM, letting you plug in alternative hypervisor backends while keeping KVM-first behavior as the default."}]},{"type":"paragraph","content":[{"type":"text","text":"What does that actually mean? It opens the door to backends like Firecracker and Cloud Hypervisor. KubeVirt isn''t just a KVM wrapper anymore. It''s positioning itself as a general-purpose VM management layer."}]},{"type":"heading","attrs":{"level":2,"id":"confidential-computing"},"content":[{"type":"text","text":"Confidential Computing"}]},{"type":"paragraph","content":[{"type":"text","text":"KubeVirt v1.8 adds Intel TDX (Trust Domain Extensions) attestation support. Confidential VMs can now cryptographically prove they''re running on trusted hardware. If you''re in a regulated industry running AI workloads that need hardware-attested isolation, this is directly for you."}]},{"type":"heading","attrs":{"level":2,"id":"aihpc-performance"},"content":[{"type":"text","text":"AI/HPC Performance"}]},{"type":"paragraph","content":[{"type":"text","text":"PCIe NUMA topology awareness is here, alongside other resource improvements. The result: AI and HPC workloads in VMs can hit near-native performance with GPU passthrough."}]},{"type":"paragraph","content":[{"type":"text","text":"That''s a meaningful shift. You get the flexibility of VMs without giving up the performance that GPU-accelerated workloads demand."}]},{"type":"heading","attrs":{"level":2,"id":"path-to-graduation"},"content":[{"type":"text","text":"Path to Graduation"}]},{"type":"paragraph","content":[{"type":"text","text":"With v1.8 and the project''s first live summit, a cross-industry contributor base is pushing KubeVirt toward CNCF graduation. KubeVirt joined CNCF in September 2019 and moved to Incubating in April 2022. The completed security audit was a critical step in getting there."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''re running mixed VM and container workloads on Kubernetes, especially with confidential computing requirements, v1.8 makes KubeVirt worth a serious look."}]}]}', 1774396800000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kubevirt-1-8-hypervisor-abstraction', 'rawkode', 0);
