INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('kyverno-graduates-cncf', 'Kyverno Graduates from CNCF — Policy-as-Code Goes Mainstream', 'Kyverno reaches CNCF Graduated status with full CEL adoption, completing its journey from Kubernetes admission controller to a broader policy engine for the cloud native stack.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kyverno has reached CNCF Graduated status, the highest maturity level in the CNCF project lifecycle. The announcement came at KubeCon + CloudNativeCon Europe 2026 in Amsterdam on March 24, 2026."}]},{"type":"heading","attrs":{"level":2,"id":"what-graduation-actually-requires"},"content":[{"type":"text","text":"What Graduation Actually Requires"}]},{"type":"paragraph","content":[{"type":"text","text":"This isn''t a rubber stamp. Graduation required a third-party security audit and a full security assessment led by CNCF TAG Security & Compliance. These validate that the project can handle production workloads and has a defensible security posture."}]},{"type":"heading","attrs":{"level":2,"id":"full-cel-adoption"},"content":[{"type":"text","text":"Full CEL Adoption"}]},{"type":"paragraph","content":[{"type":"text","text":"With its latest release, Kyverno has fully adopted Common Expression Language (CEL), matching the direction Kubernetes itself is heading for admission controls."}]},{"type":"paragraph","content":[{"type":"text","text":"The practical upside: Kyverno policies and Kubernetes ValidatingAdmissionPolicies now use the same expression language. Platform teams don''t need to context-switch between two policy syntaxes anymore."}]},{"type":"heading","attrs":{"level":2,"id":"beyond-kubernetes"},"content":[{"type":"text","text":"Beyond Kubernetes"}]},{"type":"paragraph","content":[{"type":"text","text":"Kyverno started as a Kubernetes-native admission controller, but it''s grown into something broader. Declarative policies are now usable across a wide range of payloads and enforcement points across the cloud native stack."}]},{"type":"heading","attrs":{"level":2,"id":"growth-since-2020"},"content":[{"type":"text","text":"Growth Since 2020"}]},{"type":"paragraph","content":[{"type":"text","text":"Since joining CNCF in 2020, Kyverno has gone from 574 GitHub stars to more than 9,000. The contributor base has expanded significantly, with adopters spanning startups to large enterprises."}]},{"type":"paragraph","content":[{"type":"text","text":"The CEL alignment is really the key story here. As Kubernetes moves toward CEL-based admission control, Kyverno''s adoption of the same expression language makes it a natural extension of the platform rather than a competing paradigm. That''s a smart bet on where the ecosystem is going."}]}]}', 1774310400000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('kyverno-graduates-cncf', 'rawkode', 0);
