INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('linux-foundation-12m-ai-security', 'Linux Foundation Secures $12.5M to Defend Open Source from AI-Generated Vulnerability Flood', 'Anthropic, AWS, GitHub, Google, Microsoft, and OpenAI fund $12.5M through OpenSSF to help open source maintainers cope with the flood of AI-generated security reports and vulnerability discoveries.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Linux Foundation announced $12.5 million in grant funding from Anthropic, AWS, GitHub, Google, Google DeepMind, Microsoft, and OpenAI to strengthen open source security against the growing flood of AI-generated vulnerability reports."}]},{"type":"heading","attrs":{"level":2,"id":"the-problem"},"content":[{"type":"text","text":"The Problem"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the problem: AI models are getting extremely good at finding vulnerabilities in open source code. That sounds great until you''re a maintainer with 200 new AI-generated security reports in your inbox and no tooling to sort the real issues from the noise. Burnout is real, and reports are piling up faster than anyone can process them."}]},{"type":"heading","attrs":{"level":2,"id":"scale-of-discovery"},"content":[{"type":"text","text":"Scale of Discovery"}]},{"type":"paragraph","content":[{"type":"text","text":"Anthropic disclosed that its Claude model found and validated more than 500 high-severity vulnerabilities in open source projects in an initial round of research. Five hundred. From one model, in one research pass. That gives you a sense of the scale we''re talking about."}]},{"type":"heading","attrs":{"level":2,"id":"funding-and-approach"},"content":[{"type":"text","text":"Funding and Approach"}]},{"type":"paragraph","content":[{"type":"text","text":"The funding will be managed by Alpha-Omega and the Open Source Security Foundation (OpenSSF). Rather than imposing new processes, the initiative plans to work directly with maintainers to develop security tooling that fits existing project workflows. Key goals include:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tools and automation for triaging AI-generated vulnerability reports"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Training and resources for maintainers"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Long-term, sustainable security solutions for open source communities"}]}]}]},{"type":"heading","attrs":{"level":2,"id":"whos-paying-for-this-and-why"},"content":[{"type":"text","text":"Who''s Paying for This, and Why"}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s the interesting part: the AI companies generating these reports are also funding the solutions. That''s a pragmatic acknowledgment that they''ve created a real burden for maintainers. If you maintain or depend on open source infrastructure, expect more CVE disclosures, and (hopefully) better tooling to process them. The firehose is already hitting CNCF projects. It''s not slowing down."}]}]}', 1773705600000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('linux-foundation-12m-ai-security', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('linux-foundation-12m-ai-security', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('llm-d-accepted-cncf-sandbox', 'llm-d Accepted as CNCF Sandbox Project — Kubernetes-Native Distributed LLM Inference Gets an Open Standard', 'The distributed LLM inference engine co-created by Red Hat, Google Cloud, IBM Research, CoreWeave, and NVIDIA joins the CNCF, establishing an open standard for inference workloads on Kubernetes.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"llm-d, the distributed LLM inference engine co-created by Red Hat, Google Cloud, IBM Research, CoreWeave, and NVIDIA, has been accepted as a CNCF Sandbox project. It''s establishing an open standard for running inference workloads on Kubernetes."}]},{"type":"paragraph","content":[{"type":"text","text":"The project launched in May 2025 with a clear vision: any model, any accelerator, any cloud. Since then AMD, Cisco, Hugging Face, Intel, Lambda, and Mistral AI have joined, along with UC Berkeley and the University of Chicago."}]},{"type":"heading","attrs":{"level":2,"id":"gateway-api-inference-extension"},"content":[{"type":"text","text":"Gateway API Inference Extension"}]},{"type":"paragraph","content":[{"type":"text","text":"llm-d serves as the primary implementation of the Kubernetes Gateway API Inference Extension (GAIE), providing inference-aware traffic management via the Endpoint Picker (EPP). In practice, that means model-aware routing, per-request criticality levels, and load balancing based on real-time model server metrics. All through standard Kubernetes APIs."}]},{"type":"heading","attrs":{"level":2,"id":"performance-at-scale"},"content":[{"type":"text","text":"Performance at Scale"}]},{"type":"paragraph","content":[{"type":"text","text":"The latest v0.5 release shows near-zero routing latency in multi-tenant SaaS scenarios and scales to roughly 120,000 tokens per second. Those are production-grade numbers."}]},{"type":"heading","attrs":{"level":2,"id":"what-this-means-for-your-inference-stack"},"content":[{"type":"text","text":"What This Means for Your Inference Stack"}]},{"type":"paragraph","content":[{"type":"text","text":"This is the strongest signal yet that LLM inference is becoming a standardized Kubernetes workload, not a bespoke deployment. If you''re choosing between vLLM, TGI, or custom inference setups, llm-d''s CNCF home and multi-vendor backing make it the safest bet for long-term interoperability."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s also the reference implementation for Gateway API Inference Extension. That means it won''t just run inference on Kubernetes. It''ll shape how inference routing works in Kubernetes for years to come."}]}]}', 1774310400000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('llm-d-accepted-cncf-sandbox', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('llm-d-accepted-cncf-sandbox', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('microcks-cncf-incubation', 'Microcks moves from CNCF Sandbox to Incubation', 'The CNCF Technical Oversight Committee voted to promote Microcks — a multi-protocol API mocking and contract-testing platform — to Incubating status, three years after Sandbox acceptance.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The CNCF Technical Oversight Committee has voted to promote Microcks from Sandbox to Incubating, according to the "},{"type":"text","text":"CNCF announcement on May 7, 2026","marks":[{"type":"link","attrs":{"href":"https://www.cncf.io/blog/2026/05/07/microcks-becomes-a-cncf-incubating-project/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":". Microcks entered the Sandbox on June 22, 2023."}]},{"type":"heading","attrs":{"level":2,"id":"what-microcks-covers-that-other-mocking-tools-dont"},"content":[{"type":"text","text":"What Microcks covers that other mocking tools don''t"}]},{"type":"paragraph","content":[{"type":"text","text":"Microcks generates live mock servers from contract documents — OpenAPI, AsyncAPI, gRPC/Protobuf, GraphQL SDL, Postman collections, and SOAP/WSDL — and runs the same artifacts as conformance tests against a real implementation. Its Async Minion component publishes and verifies messages on Kafka, MQTT, AMQP, NATS, WebSockets, Google Pub/Sub, and Amazon SQS/SNS, which is the part most other open-source mock servers don''t do."}]},{"type":"heading","attrs":{"level":2,"id":"what-the-promotion-actually-means"},"content":[{"type":"text","text":"What the promotion actually means"}]},{"type":"paragraph","content":[{"type":"text","text":"Incubation is the CNCF level that requires production adopters, documented governance, and a sustained contributor base — not just a maturity badge. The announcement lists 645 contributors, 2.5 million container image downloads in 2025, and 34 public adopters. Maintainers Laurent Broudoux (project creator, 2015) and Yacine Kheddache continue under formal CNCF vendor-neutral governance."}]},{"type":"paragraph","content":[{"type":"text","text":"If you''ve been hand-rolling Kafka or AsyncAPI mocks for integration tests, this is the boring-correct path the foundation is now backing."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Microcks becomes a CNCF incubating project","marks":[{"type":"link","attrs":{"href":"https://www.cncf.io/blog/2026/05/07/microcks-becomes-a-cncf-incubating-project/","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — CNCF, May 7, 2026"}]}]}', 1778112000000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('microcks-cncf-incubation', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('microcks-cncf-incubation', 'microcks', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('nvidia-donates-gpu-dra-driver-to-cncf', 'NVIDIA Donates GPU DRA Driver to CNCF, Open-Sources KAI Scheduler and Grove', 'NVIDIA shifts governance of its Dynamic Resource Allocation driver for GPUs to the CNCF, gets KAI Scheduler accepted as a Sandbox project, and open-sources Grove for AI inference orchestration.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NVIDIA announced at KubeCon Europe 2026 in Amsterdam that it is donating its Dynamic Resource Allocation (DRA) driver for GPUs to the Cloud Native Computing Foundation, shifting governance of the most critical piece of GPU-on-Kubernetes plumbing from a single vendor to the upstream community."}]},{"type":"paragraph","content":[{"type":"text","text":"This is a big deal. GPU orchestration in Kubernetes has been vendor-controlled territory, and NVIDIA just handed the keys to the community. AWS, Broadcom, Canonical, Google Cloud, Microsoft, Nutanix, Red Hat, and SUSE are all collaborating on the effort."}]},{"type":"heading","attrs":{"level":2,"id":"kai-scheduler-enters-cncf-sandbox"},"content":[{"type":"text","text":"KAI Scheduler Enters CNCF Sandbox"}]},{"type":"paragraph","content":[{"type":"text","text":"NVIDIA''s KAI Scheduler also joined the CNCF Sandbox. It''s a Kubernetes-native scheduler built specifically for AI workloads at scale. It handles DRA for GPUs, topology-aware placement, and hierarchical PodGroups for gang scheduling. Multiple workloads can share GPUs efficiently. That''s a direct answer to the GPU utilization problem that plagues most AI clusters."}]},{"type":"heading","attrs":{"level":2,"id":"grove-a-new-api-for-ai-inference-orchestration"},"content":[{"type":"text","text":"Grove: A New API for AI Inference Orchestration"}]},{"type":"paragraph","content":[{"type":"text","text":"NVIDIA also unveiled Grove, a new open-source Kubernetes API for orchestrating AI workloads on GPU clusters. Grove uses three hierarchical custom resources (PodCliques, PodCliqueScalingGroups, and PodCliqueSets) to describe multi-component workloads including specific roles, dependencies, scaling rules, and startup order within a single custom resource."}]},{"type":"heading","attrs":{"level":2,"id":"gpu-support-for-confidential-containers"},"content":[{"type":"text","text":"GPU Support for Confidential Containers"}]},{"type":"paragraph","content":[{"type":"text","text":"In collaboration with the CNCF''s Confidential Containers community, NVIDIA introduced GPU support for Kata Containers, lightweight virtual machines that act like containers, enabling AI workloads to run with additional protections around data confidentiality."}]},{"type":"paragraph","content":[{"type":"text","text":"GPU resource management in Kubernetes just shifted from vendor-controlled to community-governed. Platform teams can now bet on DRA as the standard abstraction for GPU allocation without single-vendor lock-in. NVIDIA is betting that a standardized, open GPU abstraction in Kubernetes will grow the total market faster than a proprietary lock-in strategy. Given the list of collaborators already on board, that bet looks solid."}]}]}', 1774310400000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('nvidia-donates-gpu-dra-driver-to-cncf', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('nvidia-donates-gpu-dra-driver-to-cncf', 'kubernetes', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('ofu-fleet-scale-gpu-efficiency-arxiv', 'Paper proposes OFU, a counter-based GPU efficiency metric validated on 608 production training jobs', 'An arXiv paper submitted on May 20 introduces Overall FLOP Utilization, a precision-agnostic GPU efficiency metric derived from two on-chip counters, and reports r = 0.78 correlation with application-level MFU across 608 production training jobs on H100 and GB200.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A paper submitted to arXiv on May 20 proposes Overall FLOP Utilization (OFU), a GPU efficiency metric derived from two on-chip counters — Tensor Pipe Activity and SM clock frequency — that needs no application-level instrumentation."}]},{"type":"heading","attrs":{"level":2,"id":"the-metric"},"content":[{"type":"text","text":"The metric"}]},{"type":"paragraph","content":[{"type":"text","text":"OFU is positioned against application-reported MFU, which requires per-workload integration that fleet operators rarely get to control. The authors argue for a hardware-level signal that any GPU exposing the two counters can produce, including H100 and GB200 across precisions. The result is a single number per device, comparable across heterogeneous workloads."}]},{"type":"heading","attrs":{"level":2,"id":"how-well-it-tracks-mfu"},"content":[{"type":"text","text":"How well it tracks MFU"}]},{"type":"paragraph","content":[{"type":"text","text":"Across 608 production training jobs, OFU correlates with application-level MFU at r = 0.78, and predicts MFU within ≤2 percentage points after applying a tile-quantization correction. The paper reports that the metric has already surfaced efficiency regressions in production deployments rather than just being demonstrated on synthetic benchmarks."}]},{"type":"heading","attrs":{"level":2,"id":"why-this-matters"},"content":[{"type":"text","text":"Why this matters"}]},{"type":"paragraph","content":[{"type":"text","text":"If a platform team has been falling back on "},{"type":"text","text":"nvidia-smi","marks":[{"type":"code"}]},{"type":"text","text":" SM-active fraction to gauge GPU utilization across a multi-tenant fleet, OFU offers a signal grounded in tensor-pipe activity rather than coarse SM occupancy — without asking application teams to integrate anything."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Instant GPU Efficiency Visibility at Fleet Scale (arXiv:2605.20799)","marks":[{"type":"link","attrs":{"href":"https://arxiv.org/abs/2605.20799","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 20, 2026."}]}]}', 1779235200000, 1779368956000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('ofu-fleet-scale-gpu-efficiency-arxiv', 'rawkode', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('openai-acquires-astral-ruff-uv', 'OpenAI Acquires Astral (Ruff, uv, ty) — Open Source Python Tooling Goes Corporate', 'OpenAI announces acquisition of Astral, the company behind Python developer tools Ruff, uv, and ty, with hundreds of millions of monthly downloads. Tools will integrate with Codex.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenAI announced the acquisition of Astral, the company behind Ruff (Python linter and formatter), uv (package manager), and ty (type checker). These tools see tens of millions of downloads per week. The deal is pending regulatory approval."}]},{"type":"heading","attrs":{"level":2,"id":"what-astral-built"},"content":[{"type":"text","text":"What Astral Built"}]},{"type":"paragraph","content":[{"type":"text","text":"Astral''s Rust-based Python tools went from zero to category-dominant in a few years. Ruff handles linting and formatting. uv handles dependency management. ty handles type checking. That''s a huge chunk of what Python developers need day to day, and these tools are often 10-100x faster than what came before them."}]},{"type":"heading","attrs":{"level":2,"id":"openais-intent"},"content":[{"type":"text","text":"OpenAI''s Intent"}]},{"type":"paragraph","content":[{"type":"text","text":"OpenAI says the tools will stay open source and continue to be built in the open. The acquisition is about accelerating Codex, OpenAI''s AI coding platform, which already has over two million weekly active users."}]},{"type":"paragraph","content":[{"type":"text","text":"But \"stay open source\" and \"stay community-governed\" aren''t the same thing."}]},{"type":"heading","attrs":{"level":2,"id":"community-reaction"},"content":[{"type":"text","text":"Community Reaction"}]},{"type":"paragraph","content":[{"type":"text","text":"The open source community isn''t convinced. Questions remain about governance, contributor agreements, and whether Ruff and uv''s roadmap will shift to serve Codex''s needs over the broader Python ecosystem. These are reasonable concerns."}]},{"type":"heading","attrs":{"level":2,"id":"the-governance-question"},"content":[{"type":"text","text":"The Governance Question"}]},{"type":"paragraph","content":[{"type":"text","text":"If your CI pipelines or Python-based infrastructure tooling (Pulumi, CDK, Dagger Python SDK, or any Python platform automation) depends on Ruff or uv, the governance model just changed. Watch the license and contributor agreements closely."}]},{"type":"paragraph","content":[{"type":"text","text":"The bigger question: should critical open source developer infrastructure be owned by AI companies? This acquisition will be a test case for that debate."}]}]}', 1773878400000, 1775217302000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('openai-acquires-astral-ruff-uv', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('openai-acquires-astral-ruff-uv', 'python', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('otel-collector-0-152-genai-normalizer', 'OpenTelemetry Collector 0.152 ships GenAI normalizer and drops Sarama from the kafkametrics receiver', 'Released May 12, OTel Collector v0.152.0 adds an alpha processor that normalizes GenAI telemetry from OpenInference and OpenLLMetry to the official OTel GenAI semantic conventions. The Sarama-based implementation inside the kafkametrics receiver is removed and a Cardinality Guardian processor lands in alpha.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OpenTelemetry Collector v0.152.0 landed on May 12, 2026 with three new alpha components in the contrib distribution and a Kafka breaking change worth scheduling around."}]},{"type":"heading","attrs":{"level":2,"id":"genai-normalizer"},"content":[{"type":"text","text":"GenAI normalizer"}]},{"type":"paragraph","content":[{"type":"text","text":"The new "},{"type":"text","text":"genainormalizer","marks":[{"type":"code"}]},{"type":"text","text":" processor normalizes GenAI telemetry attributes from OpenInference and OpenLLMetry to the official OTel GenAI Semantic Conventions. OpenInference and OpenLLMetry both shipped LLM telemetry conventions ahead of the OTel GenAI semconv work; this processor lets operators run one backend without maintaining parallel attribute schemas per instrumentation library."}]},{"type":"paragraph","content":[{"type":"text","text":"Stability is alpha — expect attribute mappings to shift as the OTel GenAI semconv itself continues to evolve."}]},{"type":"heading","attrs":{"level":2,"id":"cardinality-guardian"},"content":[{"type":"text","text":"Cardinality Guardian"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"cardinality_guardian","marks":[{"type":"code"}]},{"type":"text","text":" processor (alpha) targets metrics with unbounded label values eating telemetry budget. The release notes are sparse; the use case is straightforward enough that operators dealing with chatty labels will recognize the shape of the fix."}]},{"type":"heading","attrs":{"level":2,"id":"mcp-server-extension"},"content":[{"type":"text","text":"MCP server extension"}]},{"type":"paragraph","content":[{"type":"text","text":"A new MCP (Model Context Protocol) server extension ships in alpha. The MCP integration story for the collector is early; the extension is a starting point rather than a finished integration."}]},{"type":"heading","attrs":{"level":2,"id":"kafka-sarama-removal"},"content":[{"type":"text","text":"Kafka Sarama removal"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"receiver.kafkametricsreceiver.UseFranzGo","marks":[{"type":"code"}]},{"type":"text","text":" feature gate is now stable, and the Sarama-based Kafka implementation has been removed from the kafkametrics receiver. Anyone running a custom build of the collector that depended on Sarama needs a migration plan before bumping past 0.151."}]},{"type":"heading","attrs":{"level":2,"id":"component-renames"},"content":[{"type":"text","text":"Component renames"}]},{"type":"paragraph","content":[{"type":"text","text":"Several components were renamed to snake_case with deprecated aliases: "},{"type":"text","text":"otlpjson","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"otlp_json","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"kafkametrics","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"kafka_metrics","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"kubeletstats","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"kubelet_stats","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"roundrobin","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"round_robin","marks":[{"type":"code"}]},{"type":"text","text":". Aliases keep existing configs working; new configs should use the new names."}]},{"type":"paragraph","content":[{"type":"text","text":"Sources:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"OpenTelemetry Collector v0.152.0 release","marks":[{"type":"link","attrs":{"href":"https://github.com/open-telemetry/opentelemetry-collector-releases/releases/tag/v0.152.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":", "},{"type":"text","text":"contrib changelog","marks":[{"type":"link","attrs":{"href":"https://github.com/open-telemetry/opentelemetry-collector-contrib/blob/main/CHANGELOG.md","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 12, 2026."}]}]}', 1778544000000, 1778859423000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('otel-collector-0-152-genai-normalizer', 'rawkode', 0);
