INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('prometheus-3-12-rc-promql-window-functions-stackit-fix', 'Prometheus 3.12 RC adds time-window PromQL functions and patches a STACKIT SD secret leak', 'Prometheus v3.12.0-rc.0 introduces experimental start(), end(), range(), and step() PromQL functions, makes head-chunk lookup constant time in range queries, and closes a plaintext-secret exposure in the STACKIT service discovery via /-/config.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prometheus v3.12.0-rc.0 was tagged on May 19 as the first release candidate for the 3.12 line. It mixes a security fix, four new PromQL helpers, and a head-chunk lookup rewrite that should reduce CPU on long range queries."}]},{"type":"heading","attrs":{"level":2,"id":"promql-learns-about-its-own-window"},"content":[{"type":"text","text":"PromQL learns about its own window"}]},{"type":"paragraph","content":[{"type":"text","text":"The release notes call out four new experimental functions: \"Add "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"end()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"range()","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"step()","marks":[{"type":"code"}]},{"type":"text","text":" experimental functions.\" These expose the evaluation window directly to expressions — useful when you need a query''s behaviour to scale with the dashboard range it is rendered into, instead of being hard-coded."}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"resets()","marks":[{"type":"code"}]},{"type":"text","text":" function and "},{"type":"text","text":"rate()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"irate()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"increase()","marks":[{"type":"code"}]},{"type":"text","text":" now consider start-timestamp resets behind a feature flag, and the WAL learns to carry per-sample start timestamps under "},{"type":"text","text":"st-storage","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2,"id":"performance"},"content":[{"type":"text","text":"Performance"}]},{"type":"paragraph","content":[{"type":"text","text":"The release notes describe the headline change as: \"Make head chunk lookup in range queries constant time instead of quadratic time.\" Several mmap operations also skip stripes and series when no work is needed, and there is a FloatHistogram Kahan-add regression fix tied to Go 1.26."}]},{"type":"heading","attrs":{"level":2,"id":"security"},"content":[{"type":"text","text":"Security"}]},{"type":"paragraph","content":[{"type":"text","text":"GHSA-39j6-789q-qxvh closes a path where the STACKIT service discovery configuration \"fixes secrets being exposed in plaintext via "},{"type":"text","text":"/-/config","marks":[{"type":"code"}]},{"type":"text","text":" endpoint.\" Operators running STACKIT SD should plan to pick up the fix."}]},{"type":"heading","attrs":{"level":2,"id":"operator-facing-additions"},"content":[{"type":"text","text":"Operator-facing additions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Auto-reload-config is promoted to stable."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A new web interface, accessible from the Status menu, lets operators delete time series and clean tombstones."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"/api/v1/status/self_metrics","marks":[{"type":"code"}]},{"type":"text","text":" returns the server''s own metrics as JSON."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DigitalOcean Managed Databases and Outscale VMs get new SD modules; AWS SD adds IPv6 EC2 discovery and external-ID support."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is an RC, not GA — useful to test against, but not to point production at."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Prometheus 3.12.0-rc.0","marks":[{"type":"link","attrs":{"href":"https://github.com/prometheus/prometheus/releases/tag/v3.12.0-rc.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 19, 2026."}]}]}', 1779235200000, 1779276044000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('prometheus-3-12-rc-promql-window-functions-stackit-fix', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('prometheus-3-12-rc-promql-window-functions-stackit-fix', 'prometheus', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('spire-1-15-sigstore-stable-vault-key-manager', 'SPIRE 1.15 promotes Sigstore attestation out of experimental and adds a Vault Key Manager', 'SPIRE v1.15.0 graduates Sigstore support in the Kubernetes and Docker workload attestors, ships a HashiCorp Vault Key Manager plugin, and changes CLI JSON output in a way that will break parsers.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SPIRE v1.15.0 shipped on May 19. Two items stand out for anyone running it: Sigstore-backed attestation is no longer experimental, and there is a breaking change in CLI JSON output."}]},{"type":"heading","attrs":{"level":2,"id":"sigstore-graduates-in-the-workload-attestors"},"content":[{"type":"text","text":"Sigstore graduates in the workload attestors"}]},{"type":"paragraph","content":[{"type":"text","text":"The release notes are explicit: \"The "},{"type":"text","text":"sigstore","marks":[{"type":"code"}]},{"type":"text","text":" support in k8s and docker attestors was promoted out of experimental.\" That means matching workloads on cosign-style signature verification is now a supported configuration path for the Kubernetes and Docker workload attestors, not a feature-flag preview."}]},{"type":"heading","attrs":{"level":2,"id":"vault-key-manager"},"content":[{"type":"text","text":"Vault Key Manager"}]},{"type":"paragraph","content":[{"type":"text","text":"A new HashiCorp Vault Key Manager plugin lets SPIRE back its signing keys with Vault instead of the on-disk or cloud-KMS options. Combined with the existing Vault upstream authority plugin, this lets a Vault-centric organisation keep more of SPIRE''s key material under Vault control."}]},{"type":"heading","attrs":{"level":2,"id":"smaller-additions"},"content":[{"type":"text","text":"Smaller additions"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Docker workload attestor now supports rootless Podman."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"aws_iid","marks":[{"type":"code"}]},{"type":"text","text":" node attestor gains an "},{"type":"text","text":"account_id","marks":[{"type":"code"}]},{"type":"text","text":" selector."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Prometheus metrics sink supports TLS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PROXY protocol is supported for rate limiting behind load balancers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An experimental "},{"type":"text","text":"spiffe_id","marks":[{"type":"code"}]},{"type":"text","text":" node selector allows aliasing individual nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"WIT-SVIDs support an "},{"type":"text","text":"iss","marks":[{"type":"code"}]},{"type":"text","text":" claim."}]}]}]},{"type":"heading","attrs":{"level":2,"id":"breaking-change-to-watch"},"content":[{"type":"text","text":"Breaking change to watch"}]},{"type":"paragraph","content":[{"type":"text","text":"CLI commands no longer wrap a single object in a JSON array on output. The release notes flag this as a potentially breaking change for anyone parsing the JSON output. Automation that consumes "},{"type":"text","text":"spire-server","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"spire-agent","marks":[{"type":"code"}]},{"type":"text","text":" JSON expecting the outer array will need to be updated. The release also bumps cosign to v3 and Go to 1.26.3."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"SPIRE v1.15.0","marks":[{"type":"link","attrs":{"href":"https://github.com/spiffe/spire/releases/tag/v1.15.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 19, 2026."}]}]}', 1779235200000, 1779276044000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('spire-1-15-sigstore-stable-vault-key-manager', 'rawkode', 0);
INSERT INTO `news_technologies` (`story_id`, `technology_id`, `position`) VALUES ('spire-1-15-sigstore-stable-vault-key-manager', 'spire', 0);
INSERT INTO `news_stories` (`id`, `title`, `description`, `body`, `published_at`, `updated_at`) VALUES ('vllm-0-21-blackwell-transformers-v5', 'vLLM 0.21 lands Transformers v5 deprecation, C++20 build, and a new Blackwell attention backend', 'vLLM 0.21.0 ships on May 15 with two breaking-class changes — a C++20 compiler requirement and Transformers v4 deprecation — plus the TOKENSPEED_MLA attention backend for DeepSeek-R1 and Kimi-K25 on Blackwell.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"vLLM v0.21.0 dropped on May 15, 2026 with 367 commits from 202 contributors and two breaking-class changes that will force updates before the next image bump."}]},{"type":"heading","attrs":{"level":2,"id":"breaking-changes-to-plan-around"},"content":[{"type":"text","text":"Breaking changes to plan around"}]},{"type":"paragraph","content":[{"type":"text","text":"The release formally deprecates "},{"type":"text","text":"transformers","marks":[{"type":"code"}]},{"type":"text","text":" v4 support and tells users to migrate to v5. The build itself now requires a C++20-compatible compiler \"for compatibility with PyTorch,\" called out in the release notes as a breaking build change. Pin your CUDA + toolchain carefully on the next rebuild."}]},{"type":"heading","attrs":{"level":2,"id":"blackwell-gets-a-new-mla-attention-backend"},"content":[{"type":"text","text":"Blackwell gets a new MLA attention backend"}]},{"type":"paragraph","content":[{"type":"text","text":"The headline runtime change is the "},{"type":"text","text":"TOKENSPEED_MLA","marks":[{"type":"code"}]},{"type":"text","text":" attention backend on Blackwell, targeting DeepSeek-R1 and Kimi-K25 for both prefill and decode (model names per the release notes verbatim). KV offloading now integrates with the Hybrid Memory Allocator, and speculative decoding respects reasoning/thinking budgets — useful if you''ve been serving reasoning models with hand-tuned token caps."}]},{"type":"heading","attrs":{"level":2,"id":"what-to-do"},"content":[{"type":"text","text":"What to do"}]},{"type":"paragraph","content":[{"type":"text","text":"If you run vLLM in production, verify your build environment supports C++20 before consuming a newer wheel or image, and start the "},{"type":"text","text":"transformers","marks":[{"type":"code"}]},{"type":"text","text":" v5 migration now rather than at the next breaking jump. On Blackwell, benchmark "},{"type":"text","text":"TOKENSPEED_MLA","marks":[{"type":"code"}]},{"type":"text","text":" against your current backend before switching defaults."}]},{"type":"paragraph","content":[{"type":"text","text":"Source:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"vLLM v0.21.0 release notes","marks":[{"type":"link","attrs":{"href":"https://github.com/vllm-project/vllm/releases/tag/v0.21.0","target":null,"rel":null,"class":null,"title":null}}]},{"type":"text","text":" — May 15, 2026"}]}]}', 1778803200000, 1778848030000);
INSERT INTO `news_authors` (`story_id`, `person_id`, `position`) VALUES ('vllm-0-21-blackwell-transformers-v5', 'rawkode', 0);
